entries[370336] = { ["name"] = "Pilzsporenansammlung", ["text"] = "30 Meter Reichweite\nSofort\nGewährt Euren offensiven Fähigkeiten eine Chance, eine Spore zu beschwören, die Spielercharaktere in der Nähe mit 'Pilzwucher' belegt, wenn sie getötet wird. Dieser Effekt hält 1 Stunde lang an.\n\nPilzwucher\nVerursacht alle 1 Sek. 150 Naturschaden und erhöht die Chance auf einen kritischen Treffer mit Nahkampf-, Distanzangriffen und Zaubern um 15%.\n(Procchance: 10%, 15s Abklingzeit)" }
