entries[370630] = { ["name"] = "Rune des Glücks", ["text"] = "Sofort\nErmächtigt Kel'Thuzad und seinen Untergebenen mit nekromantischer Energie, was ihnen erhöhte Gesundheit und erhöhten Schaden gewährt. Ermächtigte Gegner bedeuten zusätzliche Belohnungen, wenn sie besiegt werden.\n\nDieser Effekt ist stapelbar und hält eine ganze Woche lang an." }
