entries[398115] = { ["name"] = "Immunisierungsgürtel", ["text"] = "Sofort\nErleidet 1% Schaden, um Euren Krankheits- oder Gifteffekt aufzuheben." }
entries[398117] = { ["name"] = "Leckerlibeutel", ["text"] = "20 Meter Reichweite\nSofort\nÖffnet den Leckerlibeutel und steckt ihn in die Tasche Eures Ziels. Dadurch wird der Schaden, den Wildtiere diesem Ziel zufügen, um 20 erhöht." }
