entries[398198] = { ["name"] = "Sturm der Schwerter", ["text"] = "20 Energie 100 Meter Reichweite\nSofort\nFinishing-Move, der Eure Parierchance erhöht. Combopunkte erhöhen die Dauer und die Parierchance:\n1 Punkt: 10 Sek., 12% Parierchance\n2 Punkte: 15 Sek., 14% Parierchance\n3 Punkte: 20 Sek., 16% Parierchance\n4 Punkte: 25 Sek., 18% Parierchance\n5 Punkte: 30 Sek., 20% Parierchance" }
