entries[398538] = { ["name"] = "Armschiene mit Rune prägen - Schwache Abwehr", ["text"] = "Wirken in 5 sek.\nBenötigt Armschienen\nTools: Runenverzierte Kupferrute\nReagenzien:\nGeringe Magieessenz , Seltsamer Staub\nArmschienen dauerhaft verzaubern, sodass die Verteidigungsfertigkeit des Trägers um 1 erhöht wird." }
