entries[399954] = { ["name"] = "Brustrunenfähigkeit", ["text"] = "Sofort\nLegt einen Gegenstand mit eingeprägter Rune für den Brustplatz an, um eine Fähigkeit in diesem Ausrüstungsplatz zu aktivieren." }
entries[399956] = { ["name"] = "Verstümmeln", ["text"] = "40 Energie Nahkampfreichweite\nSofort" }
entries[399960] = { ["name"] = "Verstümmeln", ["text"] = "Nahkampfreichweite\nSofort\nGreift sofort mit beiden Waffen an, verursacht 100% Waffenschaden sowie mit jeder Waffe zusätzlich [Quellwert] Schaden. Der Schaden gegen vergiftete Ziele ist um 20% erhöht. Gewährt 2 Combopunkte.", ["unresolvedValues"] = true }
entries[399961] = { ["name"] = "Verstümmeln", ["text"] = "Nahkampfreichweite\nSofort\nGreift sofort mit beiden Waffen an, verursacht 100% Waffenschaden sowie mit jeder Waffe zusätzlich [Quellwert] Schaden. Der Schaden gegen vergiftete Ziele ist um 20% erhöht. Gewährt 2 Combopunkte.", ["unresolvedValues"] = true }
entries[399962] = { ["name"] = "Verstümmeln" }
entries[399963] = { ["name"] = "Vergiften", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der sofort Giftschaden abhängig von den Dosen 'Tödliches Gift' auf dem Ziel verursacht. Nach einem Angriff mit 'Vergiften' ist die Frequenz, mit der das Ziel mit 'Sofort wirkendes Gift' belegt werden kann, für 1 Sek. plus je 1 weitere Sekunde pro Combopunkt um 75% erhöht. Pro Combopunkt wird eine Dosis aktiviert:\n1 Dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) + Angriffskraft * 0.072] Schaden\n2 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 2 + Angriffskraft * 0.144] Schaden\n3 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 3 + Angriffskraft * 0.216] Schaden\n4 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 4 + Angriffskraft * 0.288] Schaden\n5 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 5 + Angriffskraft * 0.36] Schaden" }
entries[399965] = { ["name"] = "Tödliche Mischung", ["text"] = "Gewährt Euren Giften mehrere Verbesserungen:\n\nWenn Ihr das Ziel mit irgendeinem anderen Gift vergiftet, belegt Ihr es auch mit tödlichem Gift.\n\nWenn Eure Waffe mit keinem Gift überzogen ist, besteht eine Chance, dass sie sofort wirkendes Gift anwendet, als wäre sie mit sofort wirkendem Gift überzogen.\n\nDer Schaden des tödlichen Gifts und des sofort wirkenden Gifts wird nun durch Eure Angriffskraft erhöht.\n\nEuer 'Tödliches Gift' kann jetzt gegen Ziele wirken, die bereits vom 'Tödlichen Gift' eines anderen Schurken betroffen sind." }
entries[399966] = { ["name"] = "Beinrunenfähigkeit", ["text"] = "Sofort\nLegt einen Gegenstand mit eingeprägter Rune für den Beinplatz an, um eine Fähigkeit in diesem Ausrüstungsplatz zu aktivieren." }
entries[399967] = { ["name"] = "Handrunenfähigkeit", ["text"] = "Sofort\nLegt einen Gegenstand mit eingeprägter Rune für den Handplatz an, um eine Fähigkeit in diesem Ausrüstungsplatz zu aktivieren." }
entries[399968] = { ["name"] = "Vergiften", ["text"] = "Erhaltet die Fähigkeit 'Vergiften':\n\nFinishing-Move, der sofort Giftschaden abhängig von den Dosen 'Tödliches Gift' auf dem Ziel verursacht. Nach einem Angriff mit 'Vergiften' ist die Frequenz, mit der das Ziel mit 'Sofort wirkendes Gift' belegt werden kann, für 1 Sek. plus je 1 weitere Sekunde pro Combopunkt um 75% erhöht. Pro Combopunkt wird eine Dosis aktiviert:\n1 Dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) + Angriffskraft * 0.072] Schaden\n2 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 2 + Angriffskraft * 0.144] Schaden\n3 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 3 + Angriffskraft * 0.216] Schaden\n4 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 4 + Angriffskraft * 0.288] Schaden\n5 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 5 + Angriffskraft * 0.36] Schaden" }
entries[399969] = { ["name"] = "Tödliche Mischung", ["text"] = "Erhaltet die Fähigkeit 'Tödliche Mischung':\n\nGewährt Euren Giften mehrere Verbesserungen:\n\nWenn Ihr das Ziel mit irgendeinem anderen Gift vergiftet, belegt Ihr es auch mit tödlichem Gift.\n\nWenn Eure Waffe mit keinem Gift überzogen ist, besteht eine Chance, dass sie sofort wirkendes Gift anwendet, als wäre sie mit sofort wirkendem Gift überzogen.\n\nDer Schaden des tödlichen Gifts und des sofort wirkenden Gifts wird nun durch Eure Angriffskraft erhöht.\n\nEuer 'Tödliches Gift' kann jetzt gegen Ziele wirken, die bereits vom 'Tödlichen Gift' eines anderen Schurken betroffen sind." }
entries[399985] = { ["name"] = "Schattenschlag", ["text"] = "20 Energie 25 Meter Reichweite\nSofort\nBenötigt Nahkampfwaffe\nBenötigt Verstohlenheit\nTeleportiert Euch hinter Euer Ziel und schlägt zu, um ihm 150% Waffenschaden zuzufügen. Muss im Verstohlenheitsmodus sein. Gewährt 1 Combopunkt." }
entries[399986] = { ["name"] = "Shurikenwurf", ["text"] = "30 Energie 25 Meter Reichweite\nSofort 20 sek. Abklingzeit\nWirft einen Shuriken auf Euren Gegner, der Schaden in Höhe von 50% Eurer Angriffskraft verursacht und bis zu 4 weitere Gegner in der Nähe trifft. Gewährt 1 Combopunkt pro getroffenem Ziel." }
entries[400009] = { ["name"] = "Zwischen die Augen", ["text"] = "35 Energie 20 Meter Reichweite\n20 sek. Abklingzeit\nBenötigt Distanzwaffe\nFinishing-Move für den Distanzkampf, der durch Angriffskraft erhöhten Schaden pro Combopunkt verursacht und das Ziel betäubt:\n\n1 Punkt: [Quellwert] bis [Quellwert] Schaden, 1 Sek. Betäubung\n2 Punkte: [Quellwert] bis [Quellwert] Schaden, 2 Sek. Betäubung\n3 Punkte: [Quellwert] bis [Quellwert] Schaden, 3 Sek. Betäubung\n4 Punkte: [Quellwert] bis [Quellwert] Schaden, 4 Sek. Betäubung\n5 Punkte: [Quellwert] bis [Quellwert] Schaden, 5 Sek. Betäubung\n\nTeilt sich die Abklingzeit mit 'Nierenhieb'.", ["unresolvedValues"] = true }
entries[400012] = { ["name"] = "Klingentanz", ["text"] = "25 Energie 100 Meter Reichweite\nSofort\nFinishing-Move, der Eure Parierchance um 10% erhöht und Euch 4 Angriffskraft pro Punkt Eurer Verteidigungsfähigkeit über ( 60 * 5) hinaus gewährt. Hält pro Combopunkt länger an:\n\n1 Punkt: 14 Sek.\n2 Punkte: 18 Sek.\n3 Punkte: 22 Sek.\n4 Punkte: 26 Sek.\n5 Punkte: 30 Sek." }
entries[400014] = { ["name"] = "Nur eine Fleischwunde", ["text"] = "Ihr erleidet 20% weniger körperlichen Schaden, während 'Klingentanz' aktiv ist, verringert um weitere 1% pro 12 Punkte Eurer Verteidigungsfähigkeit über ( 60 * 5) hinaus. Außerdem wird Eure Ausweichchance mit 50% multipliziert und die Chance, dass Ihr kritische Treffer durch Nahkampfangriffe erleidet, um 6% verringert, Ihr verursacht 20% weniger Schaden, die Bedrohung durch all Eure Aktionen ist massiv erhöht und Eure Fähigkeit 'Finte' wird durch 'Reizen' ersetzt. 'Reizen' verspottet das Ziel, damit es Euch angreift.\n\nVerspottet das Ziel, damit es Euch angreift. Hat keinen Effekt, wenn Ihr von dem Ziel bereits angegriffen werdet." }
entries[400015] = { ["name"] = "Schläge abschwächen" }
entries[400016] = { ["name"] = "Schläge abschwächen", ["text"] = "Jedes Mal, wenn Ihr ausweicht oder pariert, erhaltet Ihr 5% mehr Gesundheit. Bis zu 5-mal stapelbar." }
entries[400023] = { ["name"] = "Von der Schippe springen", ["text"] = "Sofort\nEin Angriff, der Euch töten würde, verringert Eure Gesundheit lediglich auf 10% Eurer maximalen Gesundheit. Außerdem wird sämtlicher erlittener Schaden 3 Sek. lang um bis zu 90% verringert. Dieser Effekt kann nicht öfter als einmal pro Minute auftreten." }
entries[400024] = { ["name"] = "Von der Schippe springen", ["text"] = "Sofort\nEin Angriff, der Euch töten würde, verringert Eure Gesundheit lediglich auf 10% Eurer maximalen Gesundheit. Außerdem wird sämtlicher erlittener Schaden 3 Sek. lang um bis zu 90% verringert. Dieser Effekt kann nicht öfter als einmal pro Minute auftreten." }
entries[400029] = { ["name"] = "Schattenschritt", ["text"] = "25 Meter Reichweite\nSofort 30 sek. Abklingzeit\nVersucht, in die Schatten zu tauchen, um hinter dem Gegner zu erscheinen. Erhöht 3 Sek. lang die Bewegungsgeschwindigkeit um 70%." }
entries[400031] = { ["name"] = "Schattenschlag", ["text"] = "Erhaltet die Fähigkeit 'Schattenschlag':\n\nTeleportiert Euch hinter Euer Ziel und schlägt zu, um ihm 150% Waffenschaden zuzufügen. Muss im Verstohlenheitsmodus sein. Gewährt 1 Combopunkt." }
entries[400032] = { ["name"] = "Shurikenwurf", ["text"] = "Erhaltet die Fähigkeit 'Shurikenwurf':\n\nWirft einen Shuriken auf Euren Gegner, der Schaden in Höhe von 50% Eurer Angriffskraft verursacht und bis zu 4 weitere Gegner in der Nähe trifft. Gewährt 1 Combopunkt pro getroffenem Ziel." }
entries[400033] = { ["name"] = "Zwischen die Augen", ["text"] = "Erhaltet die Fähigkeit 'Zwischen die Augen':\n\nFinishing-Move für den Distanzkampf, der durch Angriffskraft erhöhten Schaden pro Combopunkt verursacht und das Ziel betäubt:\n\n1 Punkt: [Quellwert] bis [Quellwert] Schaden, 1 Sek. Betäubung\n2 Punkte: [Quellwert] bis [Quellwert] Schaden, 2 Sek. Betäubung\n3 Punkte: [Quellwert] bis [Quellwert] Schaden, 3 Sek. Betäubung\n4 Punkte: [Quellwert] bis [Quellwert] Schaden, 4 Sek. Betäubung\n5 Punkte: [Quellwert] bis [Quellwert] Schaden, 5 Sek. Betäubung\n\nTeilt sich die Abklingzeit mit 'Nierenhieb'.", ["unresolvedValues"] = true }
entries[400037] = { ["name"] = "Schattenschritt", ["text"] = "Erhaltet die Fähigkeit 'Schattenschritt':\n\nVersucht, in die Schatten zu tauchen, um hinter dem Gegner zu erscheinen. Erhöht 3 Sek. lang die Bewegungsgeschwindigkeit um 70%." }
entries[400038] = { ["name"] = "Klingentanz", ["text"] = "Erhaltet die Fähigkeit 'Klingentanz':\n\nFinishing-Move, der Eure Parierchance um 10% erhöht und Euch 4 Angriffskraft pro Punkt Eurer Verteidigungsfähigkeit über ( 60 * 5) hinaus gewährt. Hält pro Combopunkt länger an:\n\n1 Punkt: 14 Sek.\n2 Punkte: 18 Sek.\n3 Punkte: 22 Sek.\n4 Punkte: 26 Sek.\n5 Punkte: 30 Sek." }
entries[400039] = { ["name"] = "Nur eine Fleischwunde", ["text"] = "Erhaltet die Fähigkeit 'Nur eine Fleischwunde':\n\nIhr erleidet 20% weniger körperlichen Schaden, während 'Klingentanz' aktiv ist, verringert um weitere 1% pro 12 Punkte Eurer Verteidigungsfähigkeit über ( 60 * 5) hinaus. Außerdem wird Eure Ausweichchance mit 50% multipliziert und die Chance, dass Ihr kritische Treffer durch Nahkampfangriffe erleidet, um 6% verringert, Ihr verursacht 20% weniger Schaden, die Bedrohung durch all Eure Aktionen ist massiv erhöht und Eure Fähigkeit 'Finte' wird durch 'Reizen' ersetzt. 'Reizen' verspottet das Ziel, damit es Euch angreift.\n\nVerspottet das Ziel, damit es Euch angreift. Hat keinen Effekt, wenn Ihr von dem Ziel bereits angegriffen werdet." }
entries[400040] = { ["name"] = "Schläge abschwächen", ["text"] = "Erhaltet die Fähigkeit 'Schläge abschwächen':\n\nJedes Mal, wenn Ihr ausweicht oder pariert, erhaltet Ihr 5% mehr Gesundheit. Bis zu 5-mal stapelbar." }
entries[400080] = { ["name"] = "Brustteil prägen - Tödliche Mischung", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Tödliche Mischung':\n\nGewährt Euren Giften mehrere Verbesserungen:\n\nWenn Ihr das Ziel mit irgendeinem anderen Gift vergiftet, belegt Ihr es auch mit tödlichem Gift.\n\nWenn Eure Waffe mit keinem Gift überzogen ist, besteht eine Chance, dass sie sofort wirkendes Gift anwendet, als wäre sie mit sofort wirkendem Gift überzogen.\n\nDer Schaden des tödlichen Gifts und des sofort wirkenden Gifts wird nun durch Eure Angriffskraft erhöht.\n\nEuer 'Tödliches Gift' kann jetzt gegen Ziele wirken, die bereits vom 'Tödlichen Gift' eines anderen Schurken betroffen sind." }
entries[400081] = { ["name"] = "Hosen prägen - Zwischen die Augen", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Zwischen die Augen':\n\nFinishing-Move für den Distanzkampf, der durch Angriffskraft erhöhten Schaden pro Combopunkt verursacht und das Ziel betäubt:\n\n1 Punkt: [Quellwert] bis [Quellwert] Schaden, 1 Sek. Betäubung\n2 Punkte: [Quellwert] bis [Quellwert] Schaden, 2 Sek. Betäubung\n3 Punkte: [Quellwert] bis [Quellwert] Schaden, 3 Sek. Betäubung\n4 Punkte: [Quellwert] bis [Quellwert] Schaden, 4 Sek. Betäubung\n5 Punkte: [Quellwert] bis [Quellwert] Schaden, 5 Sek. Betäubung\n\nTeilt sich die Abklingzeit mit 'Nierenhieb'.", ["unresolvedValues"] = true }
entries[400082] = { ["name"] = "Brustteil prägen - Nur eine Fleischwunde", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Nur eine Fleischwunde':\n\nIhr erleidet 20% weniger körperlichen Schaden, während 'Klingentanz' aktiv ist, verringert um weitere 1% pro 12 Punkte Eurer Verteidigungsfähigkeit über ( 60 * 5) hinaus. Außerdem wird Eure Ausweichchance mit 50% multipliziert und die Chance, dass Ihr kritische Treffer durch Nahkampfangriffe erleidet, um 6% verringert, Ihr verursacht 20% weniger Schaden, die Bedrohung durch all Eure Aktionen ist massiv erhöht und Eure Fähigkeit 'Finte' wird durch 'Reizen' ersetzt. 'Reizen' verspottet das Ziel, damit es Euch angreift.\n\nVerspottet das Ziel, damit es Euch angreift. Hat keinen Effekt, wenn Ihr von dem Ziel bereits angegriffen werdet." }
entries[400093] = { ["name"] = "Stiefel prägen - Schläge abschwächen", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel\nPrägt Eure Stiefel mit der Rune 'Schläge abschwächen':\n\nJedes Mal, wenn Ihr ausweicht oder pariert, erhaltet Ihr 5% mehr Gesundheit. Bis zu 5-mal stapelbar." }
entries[400094] = { ["name"] = "Handschuhe prägen - Verstümmeln", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe" }
entries[400095] = { ["name"] = "Brustteil prägen - Pistolenheld", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust" }
entries[400096] = { ["name"] = "Gürtel prägen - Shurikenwurf", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Shurikenwurf':\n\nWirft einen Shuriken auf Euren Gegner, der Schaden in Höhe von 50% Eurer Angriffskraft verursacht und bis zu 4 weitere Gegner in der Nähe trifft. Gewährt 1 Combopunkt pro getroffenem Ziel." }
entries[400099] = { ["name"] = "Hosen prägen - Klingentanz", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Klingentanz':\n\nFinishing-Move, der Eure Parierchance um 10% erhöht und Euch 4 Angriffskraft pro Punkt Eurer Verteidigungsfähigkeit über ( 60 * 5) hinaus gewährt. Hält pro Combopunkt länger an:\n\n1 Punkt: 14 Sek.\n2 Punkte: 18 Sek.\n3 Punkte: 22 Sek.\n4 Punkte: 26 Sek.\n5 Punkte: 30 Sek." }
entries[400101] = { ["name"] = "Gürtel prägen - Schattenschritt", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Schattenschritt':\n\nVersucht, in die Schatten zu tauchen, um hinter dem Gegner zu erscheinen. Erhöht 3 Sek. lang die Bewegungsgeschwindigkeit um 70%." }
entries[400102] = { ["name"] = "Hosen prägen - Vergiften", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Vergiften':\n\nFinishing-Move, der sofort Giftschaden abhängig von den Dosen 'Tödliches Gift' auf dem Ziel verursacht. Nach einem Angriff mit 'Vergiften' ist die Frequenz, mit der das Ziel mit 'Sofort wirkendes Gift' belegt werden kann, für 1 Sek. plus je 1 weitere Sekunde pro Combopunkt um 75% erhöht. Pro Combopunkt wird eine Dosis aktiviert:\n1 Dosis: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) + Angriffskraft * 0.072] Schaden\n2 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 2 + Angriffskraft * 0.144] Schaden\n3 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 3 + Angriffskraft * 0.216] Schaden\n4 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 4 + Angriffskraft * 0.288] Schaden\n5 Dosen: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 5 + Angriffskraft * 0.36] Schaden" }
entries[400104] = { ["name"] = "Hosen prägen - Schattenschritt", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Schattenschritt':\n\nVersucht, in die Schatten zu tauchen, um hinter dem Gegner zu erscheinen. Erhöht 3 Sek. lang die Bewegungsgeschwindigkeit um 70%." }
entries[400105] = { ["name"] = "Handschuhe prägen - Schattenschlag", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Schattenschlag':\n\nTeleportiert Euch hinter Euer Ziel und schlägt zu, um ihm 150% Waffenschaden zuzufügen. Muss im Verstohlenheitsmodus sein. Gewährt 1 Combopunkt." }
entries[400573] = { ["name"] = "Arkanschlag", ["text"] = "Sofort 3 min Abklingzeit\nÜberzieht einen Gegner mit Energie und verursacht Arkanschaden. Mit jedem Wirken von 'Arkanschlag' werden der verursachte Schaden und die hervorgerufene Heilung aller anderen Arkanzauber um 15% und die Manakosten von 'Arkanschlag' um 175% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar und hält 6 Sek. lang an." }
entries[400574] = { ["name"] = "Arkanschlag", ["text"] = "7% von Grundmana 30 Meter Reichweite\nWirken in 2.5 sek.\nÜberzieht das Ziel mit Energie und verursacht [Quellwert] bis [Quellwert] Arkanschaden. Mit jedem Wirken von 'Arkanschlag' wird der verursachte Schaden aller anderen Arkanzauber um 15% und die Manakosten von 'Arkanschlag' werden um 175% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar und hält 6 Sek. lang an oder bis ein anderer Arkanschadenszauber gewirkt wird.", ["unresolvedValues"] = true }
entries[400586] = { ["name"] = "Arkanschlag", ["text"] = "Sofort 3 min Abklingzeit\nÜberzieht einen Gegner mit Energie und verursacht Arkanschaden. Mit jedem Wirken von 'Arkanschlag' werden der verursachte Schaden aller anderen Arkanzauber um 15% und die Manakosten von 'Arkanschlag' um 175% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar und hält 6 Sek. lang an." }
entries[400588] = { ["name"] = "Geschosssalve", ["text"] = "Verleiht Eurem Zauber 'Arkanschlag' eine Chance von 40% sowie Euren Zaubern 'Feuerball' und 'Frostblitz' eine Chance von 20%, die Kanalisierungsdauer Eures nächsten Einsatzes von 'Arkane Geschosse' um 50% zu verringern, die Manakosten um 100% zu verringern und alle 0,5 Sek. Geschosse abzufeuern.\n(Procchance: 50%)" }
entries[400589] = { ["name"] = "Geschosssalve", ["text"] = "Sofort\nVerleiht Euren Zaubern 'Arkanschlag', 'Feuerball' und 'Frostblitz' eine Chance, die Kanalisierungsdauer Eures nächsten Wirkens von 'Arkane Geschosse' um 50% zu verringern, die Manakosten um 100% zu verringern und alle 0,5 Sek. Geschosse zu feuern." }
entries[400610] = { ["name"] = "Arkanbeschuss", ["text"] = "8% von Grundmana 30 Meter Reichweite\nSofort 3 sek. Abklingzeit\nSchleudert mehrere Geschosse auf das gegnerische Ziel und verursacht [Quellwert] bis [Quellwert] Arkanschaden. Dieser Zauber hat außerdem eine Chance von 25%, 'Geschosssalve' auszulösen.", ["unresolvedValues"] = true }
entries[400613] = { ["name"] = "Lebende Bombe", ["text"] = "22% von Grundmana 35 Meter Reichweite\nSofort" }
entries[400614] = { ["name"] = "Lebende Bombe", ["text"] = "100 Meter Reichweite\nSofort\nDas Ziel wird zu einer lebenden Bombe und erleidet im Verlauf von bis Abbruch [Quellwert] Feuerschaden. Nach Ablauf von bis Abbruch, oder wenn der Zauber gebannt wird, explodiert das Ziel und fügt allen Gegnern innerhalb von 10 Metern [Quellwert] Feuerschaden zu.", ["unresolvedValues"] = true }
entries[400615] = { ["name"] = "Überhitzen", ["text"] = "'Feuerschlag' trifft immer kritisch, kann gewirkt werden, während Ihr einen anderen Zauber wirkt, und ist nicht von der globalen Abklingzeit betroffen. Die Abklingzeit ist jedoch um 15 Sek. erhöht." }
entries[400616] = { ["name"] = "Feuerschlag", ["text"] = "115 Mana 20 Meter Reichweite\nSofort 15 sek. Abklingzeit\nÜberzieht den Gegner mit 110 bis 134 Feuerschaden." }
entries[400618] = { ["name"] = "Feuerschlag", ["text"] = "40 Mana 20 Meter Reichweite\nSofort 15 sek. Abklingzeit\nÜberzieht den Gegner mit 27 bis 35 Feuerschaden." }
entries[400619] = { ["name"] = "Feuerschlag", ["text"] = "75 Mana 20 Meter Reichweite\nSofort 15 sek. Abklingzeit\nÜberzieht den Gegner mit 62 bis 76 Feuerschaden." }
entries[400620] = { ["name"] = "Feuerschlag", ["text"] = "165 Mana 20 Meter Reichweite\nSofort 15 sek. Abklingzeit\nÜberzieht den Gegner mit 177 bis 211 Feuerschaden." }
entries[400621] = { ["name"] = "Feuerschlag", ["text"] = "220 Mana 20 Meter Reichweite\nSofort 15 sek. Abklingzeit\nÜberzieht den Gegner mit 253 bis 301 Feuerschaden." }
entries[400622] = { ["name"] = "Feuerschlag", ["text"] = "280 Mana 20 Meter Reichweite\nSofort 15 sek. Abklingzeit\nÜberzieht den Gegner mit 345 bis 407 Feuerschaden." }
entries[400623] = { ["name"] = "Feuerschlag", ["text"] = "340 Mana 20 Meter Reichweite\nSofort 15 sek. Abklingzeit\nÜberzieht den Gegner mit 446 bis 524 Feuerschaden." }
entries[400624] = { ["name"] = "Kampfeshitze", ["text"] = "Jedes Mal, wenn Ihr mit 'Feuerball', 'Frostfeuerblitz', 'Qualfeuerblitz', 'Feuerschlag', 'Versengen' oder 'Lebende Bombe' 2 unregelmäßige kritische Zaubertreffer in Folge erzielt, wird Euer nächster Einsatz von 'Pyroschlag' innerhalb von 10 Sek. zu einem Spontanzauber und kostet 100% weniger Mana." }
entries[400625] = { ["name"] = "Kampfeshitze", ["text"] = "Sofort\nJedes Mal, wenn Ihr mit 'Feuerball', 'Feuerschlag', 'Versengen', 'Lebende Bombe', 'Zauberfeuer' oder 'Frostfeuerblitz' 2 kritische Zaubertreffer in Folge erzielt, besteht eine Chance, dass Euer nächster innerhalb von 10 Sek. gewirkter 'Pyroschlag' zu einem Spontanzauber wird." }
entries[400640] = { ["name"] = "Eislanze", ["text"] = "8% von Grundmana 30 Meter Reichweite\nSofort" }
entries[400647] = { ["name"] = "Eisige Finger", ["text"] = "Verleiht Euren Kälteeffekten eine Chance von 25%, den Effekt 'Eisige Finger' hervorzurufen. Die eisigen Finger bewirken, dass Eure nächsten 2 gewirkten Zauber einen Effekt haben, den sie auf ein gefrorenes Ziel hätten. Hält 15 Sek. lang an." }
entries[400669] = { ["name"] = "Eisige Finger", ["text"] = "Sofort\nVerleiht Euren Kälteeffekten eine Chance, den Effekt 'Eisige Finger' hervorzurufen, durch den Eure nächsten gewirkten Zauber einen Effekt haben, den sie auf ein gefrorenes Ziel hätten. Hält 15 Sek. lang an." }
entries[400670] = { ["name"] = "Eisige Finger", ["text"] = "Sofort\nVerleiht Euren Kälteeffekten eine Chance, den Effekt 'Eisige Finger' hervorzurufen, durch den Eure nächsten gewirkten Zauber einen Effekt haben, den sie auf ein gefrorenes Ziel hätten. Hält 15 Sek. lang an." }
entries[400730] = { ["name"] = "Feuerball!", ["text"] = "Sofort\nEuer nächster Einsatz von 'Feuerball', 'Zauberfrostblitz', 'Qualfeuerblitz' oder 'Frostfeuerblitz' ist ein Spontanzauber und kostet kein Mana.\nModifies Power Cost -999%:\nFeuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Frostfeuerblitz , Qualfeuerblitz , Zauberfrostblitz\n\nModifies Cast Time -9999%:\nFeuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Frostfeuerblitz , Qualfeuerblitz , Zauberfrostblitz" }
entries[400731] = { ["name"] = "Hirnfrost", ["text"] = "Eure Frostzauber mit Kälteeffekten haben eine Chance von 20%, Euren nächsten Einsatz von 'Feuerball', 'Zauberfrostblitz', 'Qualfeuerblitz' oder 'Frostfeuerblitz' zu einem Spontanzauber werden zu lassen, der kein Mana kostet.\n(Procchance: 20%)" }
entries[400735] = { ["name"] = "Zeitenleuchtfeuer", ["text"] = "100 Meter Reichweite\nSofort\nErfasst die raumzeitliche Position des Subjekts. 70% sämtlichen Arkanschadens, den der Zaubernde verursacht hat, werden für alle aktuellen Ziele von 'Zeitenleuchtfeuer' des Zaubernden in chronomantische Heilung umgewandelt. Diese Heilung ist für den Zaubernden selbst um 50% verringert und wird zudem um 80% verringert, wenn durch arkane Zauber, die mehrere Ziele gleichzeitig treffen, Schaden verursacht wird." }
entries[401405] = { ["name"] = "Chronomantische Heilung" }
entries[401417] = { ["name"] = "Regeneration", ["text"] = "28% von Grundmana 40 Meter Reichweite\nKanalisiert (Wirken in 3 sek.)\nHeilt das Ziel im Verlauf von 3 Sek. um [Quellwert] Gesundheit und belegt es für 30 Sek. mit 'Zeitenleuchtfeuer'.\n\nZeitenleuchtfeuer\n\nErfasst die raumzeitliche Position des Subjekts. 70% sämtlichen Arkanschadens, den der Zaubernde verursacht hat, werden für alle aktuellen Ziele von 'Zeitenleuchtfeuer' des Zaubernden in chronomantische Heilung umgewandelt. Diese Heilung ist für den Zaubernden selbst um 50% verringert und wird zudem um 80% verringert, wenn durch arkane Zauber, die mehrere Ziele gleichzeitig treffen, Schaden verursacht wird.", ["unresolvedValues"] = true }
entries[401460] = { ["name"] = "Rasche Regeneration", ["text"] = "32% von Grundmana 40 Meter Reichweite\nKanalisiert (Wirken in 1.5 sek.)\nHeilt das Ziel im Verlauf von 1.50 Sek. um [Quellwert] Gesundheit und belegt es für 20 Sek. mit 'Zeitenleuchtfeuer'.\n\nErfasst die raumzeitliche Position des Subjekts. 70% sämtlichen Arkanschadens, den der Zaubernde verursacht hat, werden für alle aktuellen Ziele von 'Zeitenleuchtfeuer' des Zaubernden in chronomantische Heilung umgewandelt. Diese Heilung ist für den Zaubernden selbst um 50% verringert und wird zudem um 80% verringert, wenn durch arkane Zauber, die mehrere Ziele gleichzeitig treffen, Schaden verursacht wird.", ["unresolvedValues"] = true }
entries[401462] = { ["name"] = "Zeit zurückdrehen", ["text"] = "60 Meter Reichweite\nSofort 30 sek. Abklingzeit\nEuer aktuelles mit Eurem 'Zeitenleuchtfeuer' belegtes Ziel wird sofort um sämtlichen Schaden geheilt, den es in den letzten 5 Sek. erlitten hat. Wirkungslos bei Zielen, die vor 5 Sek. nicht mit 'Zeitenleuchtfeuer' belegt waren." }
entries[401488] = { ["name"] = "Hosen prägen - Schnittis Rune", ["text"] = "Sofort\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Schattenschlag':\n\nTeleportiert Euch hinter Euer Ziel und schlägt zu, um ihm 150% Waffenschaden zuzufügen. Muss im Verstohlenheitsmodus sein. Gewährt 1 Combopunkt." }
entries[401489] = { ["name"] = "Runenschnitzen: Schnittis Rune erlernen" }
entries[401495] = { ["name"] = "Schnitti - Brief gegen Rune eintauschen" }
entries[401502] = { ["name"] = "Frostfeuerblitz", ["text"] = "14% von Grundmana 35 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Frostfeuerblitz auf den Gegner, der [Quellwert] bis [Quellwert] Frostfeuerschaden verursacht, seine Bewegungsgeschwindigkeit um 40% verringert sowie ihm zusätzlich im Verlauf von 9 Sek. [Quellwert] Frostfeuerschaden zufügt. Der Schaden dieses Zaubers wird gegen den jeweils geringeren Frost- oder Feuerwiderstandswert des Ziels gerechnet und zählt sowohl als Frost- als auch als Feuerschaden.", ["unresolvedValues"] = true }
entries[401556] = { ["name"] = "Lebende Flamme", ["text"] = "11% von Grundmana 35 Meter Reichweite\nSofort 30 sek. Abklingzeit\nBeschwört eine Zauberfeuerflamme, die sich auf das Ziel zubewegt und einen Pfad aus Zauberfeuer hinterlässt. Dieser Pfad fügt Gegnern in der Nähe pro Sekunde [Quellwert] Zauberfeuerschaden zu. Hält 10 Sek. lang an.", ["unresolvedValues"] = true }
entries[401558] = { ["name"] = "Lebende Flamme", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerursacht alle 1 Sek. [Quellwert] Feuerschaden.", ["unresolvedValues"] = true }
entries[401559] = { ["name"] = "Lebende Flamme" }
entries[401617] = { ["name"] = "Schatz ausgraben", ["text"] = "Wirken in 3 sek. 1 min Abklingzeit\nGräbt einen Schatz an dem markierten Ort aus." }
entries[401645] = { ["name"] = "Vorlage: Eislanze", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nLehrt Euch, wie Ihr Eure Ausrüstung mit Rune A verzaubert." }
entries[401681] = { ["name"] = "Zaubernotizen übersetzen", ["text"] = "Wirken in 3 sek.\nReagenzien:\nVerständnisfibel\nEntziffert die Zaubernotizen mit einer Verständnisfibel, um einen neuen Runenschnitzenzauber zu erlernen." }
