entries[401699] = { ["name"] = "Zaubernotizen übersetzen", ["text"] = "Wirken in 3 sek.\nReagenzien:\nNotizen eines Lehrlings aus Azora: Seite 1 (8)\nKombiniert 8 Notizen eines Lehrlings aus Azora, um eine neue Runenschnitzenvorlage zu entdecken." }
entries[401719] = { ["name"] = "Arkanbeschuss", ["text"] = "Erhaltet die Fähigkeit 'Arkanbeschuss':\n\nSchleudert mehrere Geschosse auf das gegnerische Ziel und verursacht [Quellwert] bis [Quellwert] Arkanschaden. Dieser Zauber hat außerdem eine Chance von 25%, 'Geschosssalve' auszulösen.", ["unresolvedValues"] = true }
entries[401722] = { ["name"] = "Umhang prägen - Arkanbeschuss", ["text"] = "Wirken in 3 sek.\nBenötigt Umhang\nPrägt Euren Umhang mit der Rune 'Arkanbeschuss':\n\nSchleudert mehrere Geschosse auf das gegnerische Ziel und verursacht [Quellwert] bis [Quellwert] Arkanschaden. Dieser Zauber hat außerdem eine Chance von 25%, 'Geschosssalve' auszulösen.", ["unresolvedValues"] = true }
entries[401724] = { ["name"] = "Kampfeshitze", ["text"] = "Erhaltet die Fähigkeit 'Kampfeshitze':\n\nJedes Mal, wenn Ihr mit 'Feuerball', 'Frostfeuerblitz', 'Qualfeuerblitz', 'Feuerschlag', 'Versengen' oder 'Lebende Bombe' 2 unregelmäßige kritische Zaubertreffer in Folge erzielt, wird Euer nächster Einsatz von 'Pyroschlag' innerhalb von 10 Sek. zu einem Spontanzauber und kostet 100% weniger Mana." }
entries[401725] = { ["name"] = "Hirnfrost", ["text"] = "Erhaltet die Fähigkeit 'Hirnfrost':\n\nEure Frostzauber mit Kälteeffekten haben eine Chance von 20%, Euren nächsten Einsatz von 'Feuerball', 'Zauberfrostblitz', 'Qualfeuerblitz' oder 'Frostfeuerblitz' zu einem Spontanzauber werden zu lassen, der kein Mana kostet." }
entries[401726] = { ["name"] = "Fortgeschrittener Schutzzauber", ["text"] = "Erhaltet die Fähigkeit 'Fortgeschrittener Schutzzauber':\n\nEure Zauber 'Manaschild', 'Frostzauberschutz' und 'Feuerzauberschutz' können jetzt auf verbündete Ziele gewirkt werden und absorbieren 100% mehr Schaden. 'Manaschild' verbraucht 50% weniger Mana pro absorbiertem Schaden. Außerdem wird 'Geringen Fluch aufheben' durch 'Großen Fluch aufheben' ersetzt.\n\nEntfernt 1 Fluch und 1 schädlichen Magieeffekt von einem verbündeten Ziel." }
entries[401729] = { ["name"] = "Arkanschlag", ["text"] = "Erhaltet die Fähigkeit 'Arkanschlag':\n\nÜberzieht das Ziel mit Energie und verursacht [Quellwert] bis [Quellwert] Arkanschaden. Mit jedem Wirken von 'Arkanschlag' wird der verursachte Schaden aller anderen Arkanzauber um 15% und die Manakosten von 'Arkanschlag' werden um 175% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar und hält 6 Sek. lang an oder bis ein anderer Arkanschadenszauber gewirkt wird.", ["unresolvedValues"] = true }
entries[401731] = { ["name"] = "Lebende Bombe" }
entries[401732] = { ["name"] = "Eislanze" }
entries[401734] = { ["name"] = "Zeit zurückdrehen", ["text"] = "Erhaltet die Fähigkeit 'Zeit zurückdrehen':\n\nEuer aktuelles mit Eurem 'Zeitenleuchtfeuer' belegtes Ziel wird sofort um sämtlichen Schaden geheilt, den es in den letzten 5 Sek. erlitten hat. Wirkungslos bei Zielen, die vor 5 Sek. nicht mit 'Zeitenleuchtfeuer' belegt waren." }
entries[401735] = { ["name"] = "Frostfeuerblitz", ["text"] = "Erhaltet die Fähigkeit 'Frostfeuerblitz':\n\nSchleudert einen Frostfeuerblitz auf den Gegner, der [Quellwert] bis [Quellwert] Frostfeuerschaden verursacht, seine Bewegungsgeschwindigkeit um 40% verringert sowie ihm zusätzlich im Verlauf von 9 Sek. [Quellwert] Frostfeuerschaden zufügt. Der Schaden dieses Zaubers wird gegen den jeweils geringeren Frost- oder Feuerwiderstandswert des Ziels gerechnet und zählt sowohl als Frost- als auch als Feuerschaden.", ["unresolvedValues"] = true }
entries[401736] = { ["name"] = "Geschosssalve", ["text"] = "Erhaltet die Fähigkeit 'Geschosssalve':\n\nVerleiht Eurem Zauber 'Arkanschlag' eine Chance von 40% sowie Euren Zaubern 'Feuerball' und 'Frostblitz' eine Chance von 20%, die Kanalisierungsdauer Eures nächsten Einsatzes von 'Arkane Geschosse' um 50% zu verringern, die Manakosten um 100% zu verringern und alle 0,5 Sek. Geschosse abzufeuern." }
entries[401737] = { ["name"] = "Überhitzen", ["text"] = "Erhaltet die Fähigkeit 'Überhitzen':\n\n'Feuerschlag' trifft immer kritisch, kann gewirkt werden, während Ihr einen anderen Zauber wirkt, und ist nicht von der globalen Abklingzeit betroffen. Die Abklingzeit ist jedoch um 15 Sek. erhöht." }
entries[401741] = { ["name"] = "Eisige Finger", ["text"] = "Erhaltet die Fähigkeit 'Eisige Finger':\n\nVerleiht Euren Kälteeffekten eine Chance von 25%, den Effekt 'Eisige Finger' hervorzurufen. Die eisigen Finger bewirken, dass Eure nächsten 2 gewirkten Zauber einen Effekt haben, den sie auf ein gefrorenes Ziel hätten. Hält 15 Sek. lang an." }
entries[401743] = { ["name"] = "Regeneration", ["text"] = "Erhaltet die Fähigkeit 'Regeneration':\n\nHeilt das Ziel im Verlauf von 3 Sek. um [Quellwert] Gesundheit und belegt es für 30 Sek. mit 'Zeitenleuchtfeuer'.\n\nZeitenleuchtfeuer\n\nErfasst die raumzeitliche Position des Subjekts. 70% sämtlichen Arkanschadens, den der Zaubernde verursacht hat, werden für alle aktuellen Ziele von 'Zeitenleuchtfeuer' des Zaubernden in chronomantische Heilung umgewandelt. Diese Heilung ist für den Zaubernden selbst um 50% verringert und wird zudem um 80% verringert, wenn durch arkane Zauber, die mehrere Ziele gleichzeitig treffen, Schaden verursacht wird.", ["unresolvedValues"] = true }
entries[401744] = { ["name"] = "Lebende Flamme", ["text"] = "Erhaltet die Fähigkeit 'Lebende Flamme':\n\nBeschwört eine Zauberfeuerflamme, die sich auf das Ziel zubewegt und einen Pfad aus Zauberfeuer hinterlässt. Dieser Pfad fügt Gegnern in der Nähe pro Sekunde [Quellwert] Zauberfeuerschaden zu. Hält 10 Sek. lang an.", ["unresolvedValues"] = true }
entries[401749] = { ["name"] = "Helm prägen - Kampfeshitze", ["text"] = "Wirken in 3 sek.\nBenötigt Helme\nPrägt Euren Helm mit der Rune 'Kampfeshitze':\n\nJedes Mal, wenn Ihr mit 'Feuerball', 'Frostfeuerblitz', 'Qualfeuerblitz', 'Feuerschlag', 'Versengen' oder 'Lebende Bombe' 2 unregelmäßige kritische Zaubertreffer in Folge erzielt, wird Euer nächster Einsatz von 'Pyroschlag' innerhalb von 10 Sek. zu einem Spontanzauber und kostet 100% weniger Mana." }
entries[401752] = { ["name"] = "Stiefel prägen - Hirnfrost", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel\nPrägt Eure Stiefel mit der Rune 'Hirnfrost':\n\nEure Frostzauber mit Kälteeffekten haben eine Chance von 20%, Euren nächsten Einsatz von 'Feuerball', 'Zauberfrostblitz', 'Qualfeuerblitz' oder 'Frostfeuerblitz' zu einem Spontanzauber werden zu lassen, der kein Mana kostet." }
entries[401754] = { ["name"] = "Helm prägen - Fortgeschrittener Schutzzauber", ["text"] = "Wirken in 3 sek.\nBenötigt Helme\nPrägt Euren Helm mit der Rune 'Fortgeschrittener Schutzzauber':\n\nEure Zauber 'Manaschild', 'Frostzauberschutz' und 'Feuerzauberschutz' können jetzt auf verbündete Ziele gewirkt werden und absorbieren 100% mehr Schaden. 'Manaschild' verbraucht 50% weniger Mana pro absorbiertem Schaden. Außerdem wird 'Geringen Fluch aufheben' durch 'Großen Fluch aufheben' ersetzt.\n\nEntfernt 1 Fluch und 1 schädlichen Magieeffekt von einem verbündeten Ziel." }
entries[401757] = { ["name"] = "Handschuhe prägen - Arkanschlag", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Arkanschlag':\n\nÜberzieht das Ziel mit Energie und verursacht [Quellwert] bis [Quellwert] Arkanschaden. Mit jedem Wirken von 'Arkanschlag' wird der verursachte Schaden aller anderen Arkanzauber um 15% und die Manakosten von 'Arkanschlag' werden um 175% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar und hält 6 Sek. lang an oder bis ein anderer Arkanschadenszauber gewirkt wird.", ["unresolvedValues"] = true }
entries[401759] = { ["name"] = "Brustteil prägen - Feuerfontäne", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil mit der Rune 'Feuerfontäne':\n\nErhöht die kritische Trefferchance aller Eurer Zauber um 15%, aber die kritischen Treffer Eurer Zauber ohne regelmäßige Effekte kosten zusätzlich 1% eures Grundmanas." }
entries[401760] = { ["name"] = "Handschuhe prägen - Eislanze", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe" }
entries[401761] = { ["name"] = "Armschienen prägen - Zeit zurückdrehen", ["text"] = "Wirken in 3 sek.\nBenötigt Armschienen\nPrägt Eure Armschienen mit der Rune 'Zeit zurückdrehen':\n\nEuer aktuelles mit Eurem 'Zeitenleuchtfeuer' belegtes Ziel wird sofort um sämtlichen Schaden geheilt, den es in den letzten 5 Sek. erlitten hat. Wirkungslos bei Zielen, die vor 5 Sek. nicht mit 'Zeitenleuchtfeuer' belegt waren." }
entries[401762] = { ["name"] = "Gürtel prägen - Frostfeuerblitz", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Frostfeuerblitz':\n\nSchleudert einen Frostfeuerblitz auf den Gegner, der [Quellwert] bis [Quellwert] Frostfeuerschaden verursacht, seine Bewegungsgeschwindigkeit um 40% verringert sowie ihm zusätzlich im Verlauf von 9 Sek. [Quellwert] Frostfeuerschaden zufügt. Der Schaden dieses Zaubers wird gegen den jeweils geringeren Frost- oder Feuerwiderstandswert des Ziels gerechnet und zählt sowohl als Frost- als auch als Feuerschaden.", ["unresolvedValues"] = true }
entries[401763] = { ["name"] = "Gürtel prägen - Geschosssalve", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Geschosssalve':\n\nVerleiht Eurem Zauber 'Arkanschlag' eine Chance von 40% sowie Euren Zaubern 'Feuerball' und 'Frostblitz' eine Chance von 20%, die Kanalisierungsdauer Eures nächsten Einsatzes von 'Arkane Geschosse' um 50% zu verringern, die Manakosten um 100% zu verringern und alle 0,5 Sek. Geschosse abzufeuern." }
entries[401764] = { ["name"] = "Umhang prägen - Überhitzen", ["text"] = "Wirken in 3 sek.\nBenötigt Umhang\nPrägt Euren Umhang mit der Rune 'Überhitzen':\n\n'Feuerschlag' trifft immer kritisch, kann gewirkt werden, während Ihr einen anderen Zauber wirkt, und ist nicht von der globalen Abklingzeit betroffen. Die Abklingzeit ist jedoch um 15 Sek. erhöht." }
entries[401765] = { ["name"] = "Brustteil prägen - Eisige Finger", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Eisige Finger':\n\nVerleiht Euren Kälteeffekten eine Chance von 25%, den Effekt 'Eisige Finger' hervorzurufen. Die eisigen Finger bewirken, dass Eure nächsten 2 gewirkten Zauber einen Effekt haben, den sie auf ein gefrorenes Ziel hätten. Hält 15 Sek. lang an." }
entries[401767] = { ["name"] = "Brustteil prägen - Regeneration", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Regeneration':\n\nHeilt das Ziel im Verlauf von 3 Sek. um [Quellwert] Gesundheit und belegt es für 30 Sek. mit 'Zeitenleuchtfeuer'.\n\nZeitenleuchtfeuer\n\nErfasst die raumzeitliche Position des Subjekts. 70% sämtlichen Arkanschadens, den der Zaubernde verursacht hat, werden für alle aktuellen Ziele von 'Zeitenleuchtfeuer' des Zaubernden in chronomantische Heilung umgewandelt. Diese Heilung ist für den Zaubernden selbst um 50% verringert und wird zudem um 80% verringert, wenn durch arkane Zauber, die mehrere Ziele gleichzeitig treffen, Schaden verursacht wird.", ["unresolvedValues"] = true }
entries[401768] = { ["name"] = "Hosen prägen - Lebende Flamme", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Lebende Flamme':\n\nBeschwört eine Zauberfeuerflamme, die sich auf das Ziel zubewegt und einen Pfad aus Zauberfeuer hinterlässt. Dieser Pfad fügt Gegnern in der Nähe pro Sekunde [Quellwert] Zauberfeuerschaden zu. Hält 10 Sek. lang an.", ["unresolvedValues"] = true }
entries[401798] = { ["name"] = "Nähe zum vergrabenen Schatz" }
entries[401847] = { ["name"] = "Kartenstücke kombinieren", ["text"] = "Wirken in 3 sek.\nReagenzien:\nRechtes oberes Kartenteil , Linkes oberes Kartenteil , Rechtes unteres Kartenteil , Linkes unteres Kartenteil\nKombiniert ein Stück mit 3 anderen, um die vollständige Karte zu erhalten." }
entries[401859] = { ["name"] = "Gebet der Besserung", ["text"] = "15% von Grundmana 40 Meter Reichweite\nSofort 10 sek. Abklingzeit\nBelegt das Ziel mit einem Zauber, der es um [Quellwert] Gesundheit heilt, wenn es das nächste Mal Schaden erleidet oder geheilt wird. Wird die Heilung ausgelöst, springt 'Gebet der Besserung' zu einem Gruppen- oder Schlachtzugsmitglied innerhalb von 20 Metern über. Springt bis zu 5-mal und hält nach jedem Sprung 30 Sek. lang an. Dieser Zauber kann nur auf einem Ziel gleichzeitig platziert werden.", ["unresolvedValues"] = true }
entries[401863] = { ["name"] = "Gebet der Besserung", ["text"] = "Unbegrenzte Reichweite\nSofort\nBelegt das Ziel mit einem Zauber, der es heilt, wenn es das nächste Mal Schaden erleidet. Wird die Heilung ausgelöst, springt 'Gebet der Besserung' zu einem Gruppen- oder Schlachtzugsmitglied innerhalb von 0 Metern über. Springt bis zu 0-mal und hält nach jedem Sprung bis Abbruch lang an. Dieser Zauber kann nur auf einem Ziel gleichzeitig platziert werden." }
entries[401877] = { ["name"] = "Gebet der Besserung", ["text"] = "Unbegrenzte Reichweite\nSofort\nBelegt das Ziel mit einem Zauber, der es heilt, wenn es das nächste Mal Schaden erleidet oder geheilt wird. Wird die Heilung ausgelöst, springt 'Gebet der Besserung' zu einem Gruppen- oder Schlachtzugsmitglied innerhalb von 0 Metern über. Springt bis zu 0-mal und hält nach jedem Sprung 30 Sek. lang an. Dieser Zauber kann nur auf einem Ziel gleichzeitig platziert werden." }
entries[401880] = { ["name"] = "Gebet der Besserung" }
entries[401882] = { ["name"] = "Gebet der Besserung" }
entries[401937] = { ["name"] = "Verbindende Heilung", ["text"] = "27% von Grundmana 40 Meter Reichweite\nWirken in 1.5 sek.\nHeilt ein verbündetes Ziel und den Zaubernden um [Quellwert] bis [Quellwert] Gesundheit. Niedrige Bedrohung. Dieser Zauber profitiert von allen Effekten, die mit 'Blitzheilung' verbunden sind, und löst diese aus.", ["unresolvedValues"] = true }
entries[401946] = { ["name"] = "Kreis der Heilung", ["text"] = "56% von Grundmana 40 Meter Reichweite\nSofort 6 sek. Abklingzeit\nHeilt alle Gruppenmitglieder des anvisierten Spielercharakters innerhalb von 43.5 Metern um ihn herum um [Quellwert] bis [Quellwert] Gesundheit.", ["unresolvedValues"] = true }
entries[401955] = { ["name"] = "Schattenwort: Tod", ["text"] = "12% von Grundmana 30 Meter Reichweite\nSofort 12 sek. Abklingzeit\nEin Wort der bindenden Dunkelheit, das dem Ziel [Quellwert] bis [Quellwert] Schattenschaden zufügt. Wenn das Ziel durch 'Schattenwort: Tod' nicht stirbt, erleidet der Zaubernde Schaden in Höhe von 50% des Schadens, der dem Ziel zugefügt werden sollte.", ["unresolvedValues"] = true }
entries[401956] = { ["name"] = "Frostiges Malheur" }
entries[401962] = { ["name"] = "Schattenwort: Tod", ["text"] = "Sofort\nEin Wort der bindenden Dunkelheit, das dem Ziel Schattenschaden zufügt. Wenn das Ziel durch 'Schattenwort: Tod' nicht stirbt, erleidet der Zaubernde so viel Schaden, wie dem Ziel zugefügt wurde." }
entries[401969] = { ["name"] = "Geteilter Schmerz", ["text"] = "Euer 'Schattenwort: Schmerz' wirkt jetzt zusätzlich auf bis zu 2 zusätzliche Ziele im Umkreis von 15 Metern." }
entries[401977] = { ["name"] = "Schattengeist", ["text"] = "30 Meter Reichweite\nSofort 5 min Abklingzeit\nErschafft einen schattenhaften Geist, der das Ziel angreift. Der Zaubernde erhält bei einem Angriff des Schattengeists 5% Mana. Hält 15 Sek. lang an." }
entries[401980] = { ["name"] = "Schattengestalt" }
entries[401981] = { ["name"] = "Erhitzen" }
entries[401984] = { ["name"] = "Manasauger", ["text"] = "Die Nahkampfangriffe des Schattengeistes entziehen dem Ziel Energie, die für seinen Meister in Mana umgewandelt wird." }
entries[401988] = { ["name"] = "Manasauger", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Nahkampfangriffe des Schattengeistes entziehen dem Ziel Energie, die für seinen Meister in Mana umgewandelt wird." }
entries[401990] = { ["name"] = "Kriechende Schatten", ["text"] = "30 Meter Reichweite\nSofort 6 sek. Abklingzeit\nKriecht durch die Schatten zum gegnerischen Ziel und erhöht 5 Sek. lang den vom Schattengeist verursachten Schaden um 15%." }
entries[401991] = { ["name"] = "Kriechende Schatten", ["text"] = "Sofort" }
entries[402000] = { ["name"] = "Seelenwehr", ["text"] = "Euer 'Machtwort: Schild' hat keine Abklingzeit mehr, kostet 15% weniger Mana, gewährt 10% zusätzlichen Basiswert und erhöht Eure Heilkraft um 10%." }
entries[402004] = { ["name"] = "Schmerzunterdrückung", ["text"] = "8% von Grundmana 40 Meter Reichweite\nSofort 3 min Abklingzeit\nVerringert sofort sämtlichen Schaden, den ein verbündetes Ziel erleidet, um 40% und erhöht den Widerstand gegen Bannzauber 8 Sek. lang um 65%." }
entries[402010] = { ["name"] = "Verwandlung geheilt", ["text"] = "Sofort\nVerwandelt zurück in die normale Gestalt." }
