entries[402174] = { ["name"] = "Sühne", ["text"] = "16% von Grundmana 30 Meter Reichweite\nKanalisiert 12 sek. Abklingzeit\nSchleudert eine Salve heiligen Lichts auf das Ziel, die einem Gegner [Quellwert] Heiligschaden zufügt oder ein verbündetes Ziel sofort sowie 2 Sek. lang alle 1 Sek. um [Quellwert] Gesundheit heilt.", ["unresolvedValues"] = true }
