entries[402289] = { ["name"] = "Sühne", ["text"] = "40 Meter Reichweite\nSofort\nSchleudert eine Salve heiligen Lichts auf das Ziel, die einem Gegner [Quellwert] Heiligschaden zufügt oder ein verbündetes Ziel sofort sowie 2 Sek. lang alle 1 Sek. um [Quellwert] Gesundheit heilt.", ["unresolvedValues"] = true }
entries[402308] = { ["name"] = "Zaubernotizen übersetzen", ["text"] = "Wirken in 3 sek.\nReagenzien:\nVerständnisamulett\nEntschlüsselt die Zaubernotizen mit einem Verständnisamulett, um einen neuen Runenschnitzenzauber zu erlernen." }
entries[402311] = { ["name"] = "Zaubernotizen übersetzen", ["text"] = "Wirken in 3 sek.\nReagenzien:\nVerständnisamulett\nEntschlüsselt die Zaubernotizen mit einem Verständnisamulett, um einen neuen Runenschnitzenzauber zu erlernen." }
entries[402319] = { ["name"] = "Zaubernotizen übersetzen", ["text"] = "Wirken in 3 sek.\nReagenzien:\nNotizen eines Lehrlings aus Azora (6)\nKombiniert 6 Notizen eines Lehrlings aus Azora, um eine neue Runenschnitzenvorlage zu erschaffen." }
