entries[402668] = { ["name"] = "Vampirberührung", ["text"] = "16% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nBelegt Euer Ziel mit Eurer 'Vampirumarmung'. Fügt dem Ziel im Verlauf von 15 Sek. [Quellwert] Schattenschaden zu und gewährt allen Gruppenmitgliedern Mana in Höhe von 2% des Schattenzauberschadens, den Ihr dem Ziel zufügt.", ["unresolvedValues"] = true }
entries[402686] = { ["name"] = "Wilde Verwandlung" }
entries[402753] = { ["name"] = "Runenschnitzen: Prägen von 'Schattenschritt' erlernen" }
