entries[402760] = { ["name"] = "Runenschnitzen: Prägen von 'Tödliche Mischung' erlernen" }
entries[402779] = { ["name"] = "Vampirberührung", ["text"] = "Unbegrenzte Reichweite\nSofort\n5% des erlittenen Schattenzauberschadens stellt Mana der Gruppe des Priesters wieder her." }
entries[402789] = { ["name"] = "Auge der Leere", ["text"] = "30 Meter Reichweite\nSofort 3 min Abklingzeit\nRuft ein Auge der Leere, das 30 Sek. lang für Euch kämpft. Das Auge kann verschiedene Flüche auf Euer Ziel wirken." }
entries[402790] = { ["name"] = "Schattenblitz", ["text"] = "5% von Grundmana 35 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Blitz aus dunkler Magie auf einen Gegner und verursacht Schattenschaden." }
entries[402791] = { ["name"] = "Fluch der Schatten", ["text"] = "20% von Grundmana 35 Meter Reichweite\nSofort\nVerflucht das Ziel und verringert 3 Min. lang seinen Schatten- und Arkanwiderstand um 75. Erhöht außerdem den erlittenen Schatten- und Arkanschaden um 10%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[402792] = { ["name"] = "Fluch der Elemente", ["text"] = "20% von Grundmana 35 Meter Reichweite\nSofort\nVerflucht das Ziel und verringert 3 Min. lang seinen Feuer- und Frostwiderstand um 75. Erhöht außerdem den erlittenen Feuer- und Frostschaden um 10%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[402794] = { ["name"] = "Fluch der Sprachen", ["text"] = "20% von Grundmana 35 Meter Reichweite\nSofort\nZwingt das Ziel, Dämonisch zu sprechen, und erhöht die Zauberzeit um 60%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem Ziel aktiv sein. Hält 3 Min. lang an." }
entries[402799] = { ["name"] = "Homunculi", ["text"] = "40 Meter Reichweite\nSofort 2 min Abklingzeit\nBricht Splitter aus Eurer Seele, um 3 Miniaturkopien von Euch zum Leben zu erwecken, die versuchen, Euer aktuelles Ziel mit einem Streitkolben, Schwert und einer Axt anzugreifen. Dadurch verringern sie das Angriffstempo, die Angriffskraft bzw. die Rüstung aller getroffenen Ziele." }
entries[402801] = { ["name"] = "Homunculi", ["text"] = "40 Meter Reichweite\nSofort 2 min Abklingzeit\nErweckt 5 Skelette zum Leben, die Euer aktuelles Ziel mit einem Streitkolben, Schwert und einer Axt angreifen. Dadurch verringern sie das Angriffstempo, die Angriffskraft bzw. die Rüstung des Ziels." }
entries[402802] = { ["name"] = "Homunculi", ["text"] = "40 Meter Reichweite\nSofort 2 min Abklingzeit\nErweckt 5 Skelette zum Leben, die Euer aktuelles Ziel mit einem Streitkolben, Schwert und einer Axt angreifen. Dadurch verringern sie das Angriffstempo, die Angriffskraft bzw. die Rüstung des Ziels." }
entries[402808] = { ["name"] = "Verkrüppeln", ["text"] = "Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nErhöht die Zeit zwischen Angriffen eines Gegners um 10%. Hält 15 Sek. lang an." }
entries[402811] = { ["name"] = "Demoralisieren", ["text"] = "Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nVerringert die Angriffskraft des Ziels um 190. Hält 15 Sek. lang an." }
entries[402818] = { ["name"] = "Erodieren", ["text"] = "Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nVerringert die Rüstung eines Gegners um 2250. Hält 15 Sek. lang an." }
entries[402832] = { ["name"] = "Gebet der Besserung", ["text"] = "Erhaltet die Fähigkeit 'Gebet der Besserung':\n\nBelegt das Ziel mit einem Zauber, der es um [Quellwert] Gesundheit heilt, wenn es das nächste Mal Schaden erleidet oder geheilt wird. Wird die Heilung ausgelöst, springt 'Gebet der Besserung' zu einem Gruppen- oder Schlachtzugsmitglied innerhalb von 20 Metern über. Springt bis zu 5-mal und hält nach jedem Sprung 30 Sek. lang an. Dieser Zauber kann nur auf einem Ziel gleichzeitig platziert werden.", ["unresolvedValues"] = true }
entries[402833] = { ["name"] = "Schattenwort: Tod", ["text"] = "Erhaltet die Fähigkeit 'Schattenwort: Tod':\n\nEin Wort der bindenden Dunkelheit, das dem Ziel [Quellwert] bis [Quellwert] Schattenschaden zufügt. Wenn das Ziel durch 'Schattenwort: Tod' nicht stirbt, erleidet der Zaubernde Schaden in Höhe von 50% des Schadens, der dem Ziel zugefügt werden sollte.", ["unresolvedValues"] = true }
entries[402834] = { ["name"] = "Seelenwehr", ["text"] = "Erhaltet die Fähigkeit 'Seelenwehr':\n\nEuer 'Machtwort: Schild' hat keine Abklingzeit mehr, kostet 15% weniger Mana, gewährt 10% zusätzlichen Basiswert und erhöht Eure Heilkraft um 10%." }
entries[402836] = { ["name"] = "Homunculi", ["text"] = "Erhaltet die Fähigkeit 'Homunculi':\n\nBricht Splitter aus Eurer Seele, um 3 Miniaturkopien von Euch zum Leben zu erwecken, die versuchen, Euer aktuelles Ziel mit einem Streitkolben, Schwert und einer Axt anzugreifen. Dadurch verringern sie das Angriffstempo, die Angriffskraft bzw. die Rüstung aller getroffenen Ziele." }
entries[402837] = { ["name"] = "Verbindende Heilung", ["text"] = "Erhaltet die Fähigkeit 'Verbindende Heilung':\n\nHeilt ein verbündetes Ziel und den Zaubernden um [Quellwert] bis [Quellwert] Gesundheit. Niedrige Bedrohung. Dieser Zauber profitiert von allen Effekten, die mit 'Blitzheilung' verbunden sind, und löst diese aus.", ["unresolvedValues"] = true }
entries[402838] = { ["name"] = "Geteilter Schmerz", ["text"] = "Erhaltet die Fähigkeit 'Geteilter Schmerz':\n\nEuer 'Schattenwort: Schmerz' wirkt jetzt zusätzlich auf bis zu 2 zusätzliche Ziele im Umkreis von 15 Metern." }
entries[402839] = { ["name"] = "Schmerzunterdrückung", ["text"] = "Erhaltet die Fähigkeit 'Schmerzunterdrückung':\n\nVerringert sofort sämtlichen Schaden, den ein verbündetes Ziel erleidet, um 40% und erhöht den Widerstand gegen Bannzauber 8 Sek. lang um 65%." }
entries[402841] = { ["name"] = "Vampirberührung", ["text"] = "Erhaltet die Fähigkeit 'Vampirberührung':\n\nBelegt Euer Ziel mit Eurer 'Vampirumarmung'. Fügt dem Ziel im Verlauf von 15 Sek. [Quellwert] Schattenschaden zu und gewährt allen Gruppenmitgliedern Mana in Höhe von 2% des Schattenzauberschadens, den Ihr dem Ziel zufügt.", ["unresolvedValues"] = true }
entries[402842] = { ["name"] = "Kreis der Heilung", ["text"] = "Erhaltet die Fähigkeit 'Kreis der Heilung':\n\nHeilt alle Gruppenmitglieder des anvisierten Spielercharakters innerhalb von 43.5 Metern um ihn herum um [Quellwert] bis [Quellwert] Gesundheit.", ["unresolvedValues"] = true }
entries[402843] = { ["name"] = "Schattengeist", ["text"] = "Erhaltet die Fähigkeit 'Schattengeist':\n\nErschafft einen schattenhaften Geist, der das Ziel angreift. Der Zaubernde erhält bei einem Angriff des Schattengeists 5% Mana. Hält 15 Sek. lang an." }
entries[402844] = { ["name"] = "Sühne", ["text"] = "Erhaltet die Fähigkeit 'Sühne':\n\nSchleudert eine Salve heiligen Lichts auf das Ziel, die einem Gegner [Quellwert] Heiligschaden zufügt oder ein verbündetes Ziel sofort sowie 2 Sek. lang alle 1 Sek. um [Quellwert] Gesundheit heilt.", ["unresolvedValues"] = true }
entries[402846] = { ["name"] = "Auge der Leere", ["text"] = "Erhaltet die Fähigkeit 'Auge der Leere':\n\nRuft ein Auge der Leere, das 30 Sek. lang für Euch kämpft. Das Auge kann verschiedene Flüche auf Euer Ziel wirken." }
entries[402848] = { ["name"] = "Hosen prägen - Gebet der Besserung", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Gebet der Besserung':\n\nBelegt das Ziel mit einem Zauber, der es um [Quellwert] Gesundheit heilt, wenn es das nächste Mal Schaden erleidet oder geheilt wird. Wird die Heilung ausgelöst, springt 'Gebet der Besserung' zu einem Gruppen- oder Schlachtzugsmitglied innerhalb von 20 Metern über. Springt bis zu 5-mal und hält nach jedem Sprung 30 Sek. lang an. Dieser Zauber kann nur auf einem Ziel gleichzeitig platziert werden.", ["unresolvedValues"] = true }
entries[402849] = { ["name"] = "Handschuhe prägen - Schattenwort: Tod", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Schattenwort: Tod':\n\nEin Wort der bindenden Dunkelheit, das dem Ziel [Quellwert] bis [Quellwert] Schattenschaden zufügt. Wenn das Ziel durch 'Schattenwort: Tod' nicht stirbt, erleidet der Zaubernde Schaden in Höhe von 50% des Schadens, der dem Ziel zugefügt werden sollte.", ["unresolvedValues"] = true }
