entries[402911] = { ["name"] = "Wütender Schlag", ["text"] = "Nahkampfreichweite\nSofort 8 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nEin wilder Schlag, der 115% Waffenschaden verursacht, jedoch nur eingesetzt werden kann, während 'Wutanfall', 'Berserkerwut' oder 'Blutrausch' aktiv ist. Jede andere Nahkampffähigkeit, die eingesetzt wird, während 'Wutanfall', 'Berserkerwut' oder 'Blutrausch' aktiv ist, verringert die verbleibende Abklingzeit von 'Wütender Schlag' um 1 Sek." }
entries[402913] = { ["name"] = "Wütende Regeneration", ["text"] = "Sofort 3 min Abklingzeit\nHeilt Euch im Verlauf von 10 Sek. um 30% Eurer maximalen Gesundheit, kann jedoch nur eingesetzt werden, während 'Wutanfall', 'Berserkerwut' oder 'Blutrausch' aktiv ist. Kann auch während Betäubung eingesetzt werden." }
entries[402922] = { ["name"] = "Präzises Timing", ["text"] = "'Zerschmettern' wird jetzt sofort eingesetzt, hat allerdings eine Abklingzeit von 6 Sek." }
entries[402927] = { ["name"] = "Siegesrausch", ["text"] = "Nahkampfreichweite\nSofort 8 sek. Abklingzeit\nGreift das Ziel sofort an. Verursacht (1 + Angriffskraft * 45 / 100) Schaden und heilt Euch um 30% Eurer maximalen Gesundheit. Kann nur innerhalb von 20 Sek., nachdem Ihr einen Gegner getötet habt, der Erfahrung oder Ehre gewährt, eingesetzt werden." }
entries[402975] = { ["name"] = "Errungener Sieg", ["text"] = "Sofort\nFolgt auf das Töten eines Gegners." }
entries[403172] = { ["name"] = "Runenschnitzen: Prägen von 'Zwischen die Augen' erlernen" }
entries[403195] = { ["name"] = "Verwüsten", ["text"] = "Während Ihr Euch in der 'Verteidigungshaltung' befindet und einen Schild tragt, verursacht 'Rüstung zerreißen' zusätzlich pro Sekunde Schaden in Höhe von 150% des Schadens Eurer ausgerüsteten Waffe. Dieser Effekt ist pro Stapel von 'Rüstung zerreißen', der bereits auf dem Ziel ist, um 15% erhöht. Schaden von 'Verwüsten' erzeugt ein hohes Maß an Bedrohung, während Ihr Euch in der 'Verteidigungshaltung' befindet." }
entries[403196] = { ["name"] = "Verwüsten", ["text"] = "Unbegrenzte Reichweite\nSofort\nBenötigt Nahkampfwaffe\n'Rüstung zerreißen' verursacht zusätzlich 150% Waffenschaden. Dieser Effekt erhöht sich pro Stapel von 'Rüstung zerreißen', der bereits auf dem Ziel ist, um 15%." }
entries[403215] = { ["name"] = "Befehlsruf", ["text"] = "Sofort\nDer Krieger schreit, wodurch sich die Ausdauer aller Gruppenmitglieder innerhalb von 30 Metern um 2 erhöht. Hält 5 Min. lang an." }
entries[403218] = { ["name"] = "Endlose Wut", ["text"] = "Ihr erhaltet 25% mehr Wut durch sämtlichen von Euch verursachten Schaden." }
entries[403219] = { ["name"] = "Wütender Donner", ["text"] = "'Donnerknall' erhöht nun die Zeit zwischen Angriffen um zusätzliche 6%, kann in jeder Haltung eingesetzt werden, verursacht 100% mehr Schaden und erzeugt 75% mehr Bedrohung." }
entries[403228] = { ["name"] = "Fleischhaken", ["text"] = "15 Wut 30 Meter Reichweite\nSpontanzauber 35 sek. Abklingzeit" }
entries[403231] = { ["name"] = "Fleischhaken", ["text"] = "Unbegrenzte Reichweite\nSofort 35 sek. Abklingzeit\nWirft einen Haken mit einer Kette aus, um das Ziel zu fesseln und zu Euch zu ziehen." }
