entries[403332] = { ["name"] = "Heldenhafter Schuss", ["text"] = "8 - 35 Meter Reichweite\n6 sek. Abklingzeit\nBenötigt Distanzwaffe\nSchießt auf das Ziel und verursacht 300% Distanzwaffenschaden. Generiert 20 Wut." }
entries[403338] = { ["name"] = "Einschreiten", ["text"] = "10 Wut 8 - 25 Meter Reichweite\nSpontanzauber 30 sek. Abklingzeit\nBenötigt Verteidigungshaltung\nLauft mit hoher Geschwindigkeit auf ein Gruppenmitglied zu, um den nächsten Nahkampf- oder Distanzangriff gegen diese Person abzufangen und seine gesamte Bedrohung um 10% zu verringern." }
