entries[403352] = { ["name"] = "Blutraserei", ["text"] = "Erhaltet die Fähigkeit 'Blutraserei':\n\n'Verwunden' kann jetzt in der Berserker-Stellung eingesetzt werden. Der Schaden von 'Verwunden' wird um 100% erhöht, und 'Verwunden' verursacht jedes Mal, wenn es Schaden verursacht, zusätzlichen Schaden in Höhe von 4% Eurer Angriffskraft." }
