entries[403858] = { ["name"] = "Heimsuchung", ["text"] = "Erhaltet die Fähigkeit 'Heimsuchung':\n\nJagt eine geisterhafte Seele auf den Gegner, die [Quellwert] bis [Quellwert] Schaden verursacht und sämtlichen regelmäßigen Schattenschaden, den Ihr dem Ziel zufügt, 15 Sek. lang um 40% erhöht. Wenn 'Heimsuchung' endet oder gebannt wird, werdet Ihr in Höhe des Schadens geheilt, die der Zauber dem Ziel zugefügt hat.", ["unresolvedValues"] = true }
