entries[403932] = { ["name"] = "Kiste prägen - Meisterkanalisierer", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Meisterkanalisierer':\n\nEuer Zauber 'Blutsauger' wird nicht mehr kanalisiert, hält 15 Sek. lang an mit einer Abklingzeit von 15 Sek., kostet 100% mehr Mana und heilt Euch jedes Mal, wenn er Schaden verursacht, um 50% mehr." }
entries[403936] = { ["name"] = "Handschuhe prägen - Schattenblitzsalve", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Schattenblitzsalve':\n\nEuer 'Schattenblitz' trifft jetzt bis zu 5 Ziele in einer Kette innerhalb von 10 Metern, aber mit um 30% verringertem Schaden." }
entries[403937] = { ["name"] = "Brustteil prägen - See des Feuers", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'See des Feuers':\n\nEuer 'Feuerregen' wird nicht mehr kanalisiert, aber erhält eine Abklingzeit von 8 Sek." }
entries[403938] = { ["name"] = "Handschuhe prägen - Metamorphose", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Metamorphose':\n\nVerwandelt Euch in einen Dämon. Eure Rüstung wird um 500% und Eure Gesundheit um 15% erhöht und die Chance, kritische Treffer zu erleiden, um 6% verringert. Eure Bedrohung wird um 50% erhöht und 'Aderlass' gewährt 100% mehr Mana, doch Euer sämtlicher verursachter Schaden wird um 10% verringert. 'Metamorphose' verändert einige Fähigkeiten und gewährt neue:\n\n'Sengender Schmerz': Wird zu einem Spontanzauber.\n\n'Schattenblitz': Wird zu 'Schattenspalten', einem Nahkampfangriff, der bis zu 10 Gegner in der Nähe mit Schattenschaden trifft, aber eine Abklingzeit von 6 Sek. hat.\n\n'Furcht': Wird durch 'Plagegeist' ersetzt.\n\nVerspottet das Ziel, damit es Euch angreift. Hat keinen Effekt, wenn Ihr von dem Ziel bereits angegriffen werdet.\n\n'Dämonischer Ansturm'\n\nStürmt auf einen Gegner zu und betäubt ihn für 1 Sek. Kann nicht im Kampf verwendet werden.\n\n'Dämonisches Heulen'\n\nZwingt alle Gegner in der Nähe 6 Sek. lang, ihre Angriffe auf Euch zu konzentrieren." }
