entries[407613] = { ["name"] = "Flamme des Glaubens", ["text"] = "7% von Grundmana 40 Meter Reichweite\nSofort\nDas Ziel wird für alle Gruppen- und Schlachtzugsmitglieder in einem Radius von 40 Metern zu einer Flamme des Glaubens. Alle auf diese Mitglieder gewirkten Heilungen heilen auch die Flamme um 75% der gewirkten Heilung. Es kann immer nur ein Ziel zur gleichen Zeit eine Flamme des Glaubens sein. Hält 1 Stunde lang an." }
entries[407614] = { ["name"] = "Glaubensflamme", ["text"] = "60 Meter Reichweite\nSofort\nDas Ziel wird für alle Ziele in einem Radius von 60 Metern zu einer Flamme des Glaubens. Alle auf diese Ziele gewirkten Heilungen heilen auch die Flamme um 75% der gewirkten Heilung." }
entries[407615] = { ["name"] = "Flamme des Glaubens", ["text"] = "40 Meter Reichweite\nSofort\nDas Ziel wird für alle Ziele in einem Radius von 40 Metern zu einer Flamme des Glaubens. Alle auf diese Ziele gewirkten Heilungen heilen auch die Flamme um 1% der gewirkten Heilung. Es kann immer nur ein Ziel zur gleichen Zeit eine Flamme des Glaubens sein. Hält bis Abbruch lang an." }
entries[407624] = { ["name"] = "Aurenmeisterschaft", ["text"] = "Sofort 2 min Abklingzeit\nVerleiht allen durch Eure Fähigkeit 'Aura der Konzentration' gestärkten Zielen Immunität gegen Unterbrechungs- und Stilleeffekte. Die Effekte aller anderen Auren werden um 100% erhöht. Hält 6 Sek. lang an." }
entries[407627] = { ["name"] = "Zorn der Gerechtigkeit", ["text"] = "Sofort\nErhöht die durch Eure Heiligzauber verursachte Bedrohung um 80%. Wenn Ihr von einem anderen verbündeten Ziel geheilt werdet, erhaltet Ihr Mana in Höhe von 25% der hervorgerufenen Heilung. Zusätzlich wird Schaden, der Eure Gesundheit unter 35% senkt, um 20% verringert. Hält bis Abbruch lang an." }
entries[407628] = { ["name"] = "Zorn der Gerechtigkeit", ["text"] = "Sofort\nGewinnt Mana durch erhaltene Heilung." }
entries[407631] = { ["name"] = "Hand der Abrechnung", ["text"] = "Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nVerspottet das Ziel, damit es Euch angreift. Hat keinen Effekt, wenn Ihr von dem Ziel bereits angegriffen werdet.\n\nWährend Ihr diese Fähigkeit kennt, ist der Bedrohungsbonus von 'Zorn der Gerechtigkeit' auf 80% erhöht. Wenn Ihr von anderen Charakteren geheilt werdet, sorgt 'Zorn der Gerechtigkeit' dafür, dass Ihr Mana in Höhe von 25% der hervorgerufenen Heilung erhaltet. Zusätzlich wird Schaden, der Eure Gesundheit unter 35% senkt, um 20% verringert, während 'Zorn der Gerechtigkeit' aktiv ist. 'Zorn der Gerechtigkeit' bleibt aktiv, bis er abgebrochen wird." }
entries[407632] = { ["name"] = "Hammer der Rechtschaffenen", ["text"] = "6% von Grundmana Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nTrifft das aktuelle Ziel sowie bis zu 3 zusätzliche Ziele in der Nähe und verursacht pro Sekunde den 4-fachen Schaden Eurer Waffenhandwaffe als Heiligschaden." }
entries[407653] = { ["name"] = "Gabelblitzschlag", ["text"] = "30 Meter Reichweite\nSofort\nTrifft einen Gegner mit einem Blitzschlag, der auf einen Gegner in der Nähe überspringt. Der Zauber wirkt sich auf bis zu 0 Ziele aus und fügt jedem Naturschaden zu." }
entries[407667] = { ["name"] = "Gabelblitzschlag", ["text"] = "30 Meter Reichweite\nSofort\nTrifft einen Feind mit einem Blitzschlag, der auf alle Ziele in der Nähe überspringt und ihnen Naturschaden zufügt." }
entries[407669] = { ["name"] = "Schild des Rächers", ["text"] = "26% von Grundmana 30 Meter Reichweite\nSofort 15 sek. Abklingzeit\nSchleudert einen heiligen Schild auf den Gegner, der [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Zaubermacht + 0.091 * Angriffskraft] bis [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Zaubermacht + 0.091 * Angriffskraft] Heiligschaden verursacht, ihn benommen macht und dann auf weitere Gegner in der Nähe überspringt. Wirkt auf insgesamt 3 Ziele. Hält 5 Sek. lang an." }
entries[407676] = { ["name"] = "Kreuzfahrerstoß", ["text"] = "Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nEin sofortiger Stoß, der 75% Waffenschaden als Heiligschaden verursacht und 5% Eures maximalen Manas regeneriert. Die Dauer aller Richturteilseffekte auf dem Ziel wird auf 30 Sek. zurückgesetzt." }
entries[407720] = { ["name"] = "Gabelblitzschlag", ["text"] = "30 Meter Reichweite\nSofort\nTrifft einen Gegner mit einem Blitzschlag, der auf einen Gegner in der Nähe überspringt. Der Zauber wirkt sich auf bis zu 0 Ziele aus und fügt jedem Naturschaden zu." }
entries[407736] = { ["name"] = "Gabelblitzschlag", ["text"] = "30 Meter Reichweite\nSofort\nTrifft einen Gegner mit einem Blitzschlag, der auf einen Gegner in der Nähe überspringt. Der Zauber wirkt sich auf bis zu 0 Ziele aus und fügt jedem Naturschaden zu." }
