entries[407778] = { ["name"] = "Göttlicher Sturm", ["text"] = "12% von Grundmana\nSofort 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nEin sofortiger Waffenangriff, der bis zu 4 Gegnern innerhalb von 8 Metern 110% Waffenschaden zufügt. 'Göttlicher Sturm' heilt bis zu 3 Gruppen- oder Schlachtzugsmitglieder in Höhe von 25% des verursachten Schadens." }
entries[407782] = { ["name"] = "Göttlicher Sturm", ["text"] = "100 Meter Reichweite\nSofort\nSchaden durch 'Göttlicher Sturm' heilt verbündete Ziele." }
entries[407784] = { ["name"] = "Göttlicher Sturm", ["text"] = "Unbegrenzte Reichweite\nSofort\nVon 'Göttlicher Sturm' verursachter Schaden heilt verbündete Ziele in der Nähe." }
entries[407788] = { ["name"] = "Zornige Vergeltung", ["text"] = "8% von Grundmana\nSofort 3 min Abklingzeit\nErhöht 20 Sek. lang jeglichen verursachten Schaden und Heilung um 20%. Verursacht 'Vorahnung' und kann nicht eingesetzt werden, während 'Vorahnung' aktiv ist." }
entries[407791] = { ["name"] = "Aku'mais Wut", ["text"] = "Sofort\nErhöht den vom Zaubernden verursachten körperlichen Schaden um 25 und sein Angriffstempo um 30%. Hält 15 Sek. lang an." }
entries[407794] = { ["name"] = "Dreifachstich", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Gegner 15 Sek. lang alle 3 Sek. körperlichen Schaden zu.\n(1s Abklingzeit)" }
