entries[407800] = { ["name"] = "Siegel des Märtyrertums", ["text"] = "Sofort\nDer Schaden von 'Siegel des Märtyrertums' fügt auch dem Paladin Schaden zu." }
entries[407802] = { ["name"] = "Siegel des Märtyrertums", ["text"] = "40 Meter Reichweite\nSofort\nGewinnt Mana aus dem Schaden, den der Paladin erleidet." }
entries[407803] = { ["name"] = "Richturteil des Märtyrertums" }
entries[407804] = { ["name"] = "Heilige Opferung", ["text"] = "Sofort 2 min Abklingzeit\n30% jeglichen von Gruppenmitgliedern im Umkreis von 30 Metern erlittenen Schadens werden 10 Sek. lang auf den Paladin umgelenkt. Schaden, der die Gesundheit des Paladins auf unter 20% senkt, bricht den Effekt ab und erhöht 10 Sek. lang den Schaden und die Heilung des Paladins um 10%. 'Heilige Opferung' kann unter dem Einfluss von 'Segen des Schutzes', 'Gottesschild' oder 'Göttlicher Schutz' nicht verwendet werden und verhindert, dass Ihr mit diesen Fähigkeiten anvisiert werden könnt, während 'Heilige Opferung' aktiv ist." }
entries[407805] = { ["name"] = "Opferung eingelöst", ["text"] = "Sofort 3 min Abklingzeit\nNach Eurer Opferung sind Euer Schaden und Eure Heilung erhöht." }
entries[407811] = { ["name"] = "Spalten", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nFügt einem Gegner und seinem nächsten Verbündeten Waffenschaden plus 23 bis 27 zu, wirkt auf bis zu 3 Ziele." }
entries[407812] = { ["name"] = "Immunität gegen 'Eiskältepfeil'" }
entries[407813] = { ["name"] = "Frostpfeil", ["text"] = "5 - 30 Meter Reichweite\nWirken in 1 sek.\nBenötigt Distanzwaffe\nSchießt auf den Gegner und verursacht körperlichen Schaden." }
entries[407819] = { ["name"] = "Frostpfeil", ["text"] = "50 Meter Reichweite\nWirken in 1.5 sek.\nBenötigt Distanzwaffe\nSchießt auf den Gegner und verursacht körperlichen Schaden." }
