entries[407880] = { ["name"] = "Inspirationsvorbild", ["text"] = "2% von Grundmana\nSofort\nEure inspirierende Präsenz bannt regelmäßig Furcht- und Schlafeffekte von Gruppenmitgliedern in der Nähe." }
entries[407881] = { ["name"] = "Inspirationsvorbild", ["text"] = "Sofort\nEure inspirierende Präsenz bannt regelmäßig Furcht- und Schlafeffekte von Gruppenmitgliedern in der Nähe." }
