entries[407973] = { ["name"] = "Wilder Stoß", ["text"] = "100 Meter Reichweite\nSofort\nZusatzangriff." }
entries[407975] = { ["name"] = "Wilde Stöße", ["text"] = "Sofort\nGruppenmitglieder im Umkreis von 20 Metern erlangen erhöhte Kampfwildheit. Bei jedem Nahkampftreffer besteht eine Chance von 20%, dem Angreifer einen Zusatzangriff mit 20% höherer Angriffskraft zu gewähren. Kein Effekt, wenn das Gruppenmitglied bereits vom Totem des Windzorns profitiert.\n(Procchance: 20%, 1.5s Abklingzeit)" }
entries[407977] = { ["name"] = "Wilde Stöße", ["text"] = "Während Ihr in Katzengestalt, Bärengestalt oder Terrorbärengestalt seid, erlangen Gruppen- oder Schlachtzugsmitglieder im Umkreis von 100 Metern erhöhte Kampfwildheit. Bei jedem Nahkampftreffer besteht eine Chance von 20%, dem Angreifer einen Zusatzangriff mit 20% höherer Angriffskraft zu gewähren. Kein Effekt, wenn das Ziel bereits vom Totem des Windzorns profitiert." }
entries[407988] = { ["name"] = "Wildes Brüllen", ["text"] = "25 Energie 100 Meter Reichweite\nSofort\nFinishing-Move, der den verursachten körperlichen Schaden in Katzengestalt um 30% erhöht. Hält pro Combopunkt länger an:\n1 Punkt: 14 Sek.\n2 Punkte: 19 Sek.\n3 Punkte: 24 Sek.\n4 Punkte: 29 Sek.\n5 Punkte: 34 Sek." }
entries[407989] = { ["name"] = "Wildes Brüllen", ["text"] = "Sofort\nBenötigt Katzengestalt\nFinishing-Move, der den verursachten körperlichen Schaden um 30% erhöht. Hält pro Combopunkt länger an:\n1 Punkt: 14 Sek.\n2 Punkte: 19 Sek.\n3 Punkte: 24 Sek.\n4 Punkte: 29 Sek.\n5 Punkte: 34 Sek." }
entries[407993] = { ["name"] = "Zerfleischen", ["text"] = "40 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nZerfleischt das Ziel, fügt ihm 270% des normalen Schadens zu und lässt es 1 Min. lang 30% zusätzlichen Schaden durch Blutungseffekte und 'Schreddern' erleiden. Gewährt 1 Combopunkt. Diese Fähigkeit profitiert von allen Effekten von 'Klaue' und 'Zermalmen' und löst diese aus." }
entries[407995] = { ["name"] = "Zerfleischen", ["text"] = "15 Wut Nahkampfreichweite\nSpontanzauber 6 sek. Abklingzeit\nBenötigt Bärengestalt, Terrorbärengestalt\nZerfleischt das Ziel, fügt ihm 160% des normalen Schadens zu und lässt es 1 Min. lang 30% zusätzlichen Schaden durch Blutungseffekte und 'Schreddern' erleiden. Diese Fähigkeit profitiert von allen Effekten von 'Klaue' und 'Zermalmen' und löst diese aus.\n\nWenn Ihr ein Ziel mit 'Zerfleischen (Bär)' trefft, erhaltet Ihr zudem 4 Angriffskraft für jeden Punkt Eurer Verteidigungsfertigkeit über ( 60 * 5). Hält 15 Sek. lang an." }
entries[408013] = { ["name"] = "Blackfathom-Elitenspawner" }
entries[408014] = { ["name"] = "Blackfathom-Elite erschaffen" }
entries[408024] = { ["name"] = "Überlebensinstinkte", ["text"] = "Sofort 3 min Abklingzeit\nNach Aktivierung erhaltet Ihr 20 Sek. lang 30% Eurer maximalen Gesundheit. Während dieser Zeit wird zudem sämtliche von Euch hervorgerufene nichtkörperliche Heilung um 20% erhöht. Nachdem der Effekt abgelaufen ist, geht die Gesundheit verloren. Kann in jeder Gestalt mit Ausnahme der Moonkingestalt eingesetzt werden.\n\nZusätzlich regeneriert Ihr bei jedem Ausweichen in Bärengestalt oder Terrorbärengestalt 5 Wut, in Katzengestalt 10 Energie oder in jeder anderen Gestalt 1% Eures maximalen Manas." }
entries[408025] = { ["name"] = "Überlebensinstinkte" }
