entries[408035] = { ["name"] = "Damien Kane - Seelen gegen Rune eintauschen" }
entries[408120] = { ["name"] = "Wildwuchs", ["text"] = "45% von Grundmana 40 Meter Reichweite\nSofort 6 sek. Abklingzeit\nHeilt alle Gruppenmitglieder des anvisierten Spielercharakters innerhalb von 43.5 Metern um ihn herum im Verlauf von 7 Sek. um [Quellwert] Gesundheit. Die Heilung wird zunächst schnell und mit zunehmender Dauer von 'Wildwuchs' langsamer angewendet.", ["unresolvedValues"] = true }
entries[408124] = { ["name"] = "Blühendes Leben", ["text"] = "14% von Grundmana 40 Meter Reichweite\nSofort\nHeilt das Ziel im Verlauf von 7 Sek. um [Quellwert] Gesundheit. Wenn 'Blühendes Leben' endet oder gebannt wird, wird das Ziel sofort um [Quellwert] Gesundheit geheilt und der Druide erhält die Hälfte der Zauberkosten erstattet. Dieser Effekt ist bis zu 3-mal auf einem Ziel stapelbar.\n(2s Abklingzeit)", ["unresolvedValues"] = true }
entries[408245] = { ["name"] = "Blühendes Leben", ["text"] = "40 Meter Reichweite\nSofort\nHeilt das Ziel im Verlauf von 7 Sek. Wenn 'Blühendes Leben' endet oder gebannt wird, wird das Ziel sofort geheilt. Dieser Effekt ist bis zu 3-mal auf einem Ziel stapelbar." }
entries[408246] = { ["name"] = "Blühendes Leben", ["text"] = "Sofort\nGewährt Mana, wenn 'Blühendes Leben' abläuft." }
entries[408247] = { ["name"] = "Pflege", ["text"] = "26% von Grundmana 40 Meter Reichweite\nWirken in 2 sek.\nHeilt ein verbündetes Ziel um [Quellwert] bis [Quellwert] Gesundheit. Wenn ein durch Euch gewirkter Effekt von 'Verjüngung', 'Nachwachsen', 'Wildwuchs' oder 'Blühendes Leben' auf dem Ziel aktiv ist, erhöht sich die Heilung um zusätzliche 20%. Dieser Zauber profitiert von allen Effekten von 'Heilende Berührung' oder 'Nachwachsen' und löst diese aus.", ["unresolvedValues"] = true }
entries[408248] = { ["name"] = "Finsternis", ["text"] = "'Sternenfeuer' erhöht die Chance auf kritische Treffer bei Euren nächsten beiden Einsätzen von 'Zorn' um 30%, und 'Zorn' verringert die Zauberzeit Eures nächsten Einsatzes von 'Sternenfeuer' um 1.0 Sek. Beide Effekte lassen sich bis zu 4-mal stapeln. Bei beiden Zaubern besteht außerdem jederzeit eine Chance von 70%, dass Ihr keine Zauberzeit verliert, wenn Ihr Schaden erleidet." }
entries[408250] = { ["name"] = "Sonnenfinsternis", ["text"] = "Sofort\nErhöht die Chance auf kritische Treffer mit 'Zorn'." }
entries[408255] = { ["name"] = "Mondfinsternis" }
entries[408258] = { ["name"] = "Traumzustand", ["text"] = "Kritische Treffer Eurer nicht regelmäßigen Schadenszauber und jeglicher Schaden von Eurem 'Sternensog' gewähren Euch 8 Sek. lang 50% Manaregeneration, während Ihr Zauber wirkt. Der Arkan- und Naturschaden gegen Ziele, bei denen es sich nicht um Spielercharaktere handelt, wird außerdem 12 Sek. lang um 20% erhöht." }
entries[408261] = { ["name"] = "Traumzustand", ["text"] = "Sofort\nErmöglicht, dass 50% Eurer Manaregeneration während des Zauberwirkens weiterlaufen." }
entries[408307] = { ["name"] = "Zorn der Natur", ["text"] = "Sofort 2 min Abklingzeit\nErhöht Eure Heilkraft 30 Sek. lang um 90% Eures Naturzauberschadens." }
entries[408309] = { ["name"] = "Anmut der Elune", ["text"] = "Sofort 2 min Abklingzeit\nErhöht Euren Zauberschaden um 55% der Differenz zwischen Eurer Heilkraft und Eurem Zauberschaden. Hält 30 Sek. lang an." }
entries[408339] = { ["name"] = "Feuernova", ["text"] = "Euer Totem der Feuernova wird durch 'Feuernova' ersetzt. Dadurch verursacht Euer derzeitiges Feuertotem Schaden an seinem Standort." }
