entries[408438] = { ["name"] = "Überladung", ["text"] = "Verleiht Euren Zaubern 'Blitzschlag', 'Kettenblitzschlag', 'Kettenheilung', 'Welle der Heilung' und 'Lavaeruption' eine Chance von 60%, kostenlos einen zweiten, ähnlichen Zauber auf das gleiche Ziel auszulösen. Dieser verursacht nur halben Schaden bzw. halbe Heilung und erzeugt keine Bedrohung.\n(Procchance: 60%)" }
