entries[408479] = { ["name"] = "Kettenblitzschlag", ["text"] = "30 Meter Reichweite\nSofort\nSchleudert einen Blitzschlag auf den Gegner, der 99 bis 114 Naturschaden verursacht und auf Gegner in der Nähe überspringt. Jeder Sprung verringert den Schaden um 30%. Wirkt auf insgesamt 3 Ziele." }
entries[408481] = { ["name"] = "Kettenblitzschlag", ["text"] = "30 Meter Reichweite\nSofort\nSchleudert einen Blitzschlag auf den Gegner, der 143 bis 162 Naturschaden verursacht und auf Gegner in der Nähe überspringt. Jeder Sprung verringert den Schaden um 30%. Wirkt auf insgesamt 3 Ziele." }
