entries[408484] = { ["name"] = "Kettenblitzschlag", ["text"] = "30 Meter Reichweite\nSofort\nSchleudert einen Blitzschlag auf den Gegner, der 252 bis 283 Naturschaden verursacht und auf Gegner in der Nähe überspringt. Jeder Sprung verringert den Schaden um 30%. Wirkt auf insgesamt 3 Ziele." }
entries[408490] = { ["name"] = "Lavaeruption", ["text"] = "10% von Grundmana 30 Meter Reichweite\nWirken in 2 sek. 8 sek. Abklingzeit\nIhr schleudert flüssige Lava auf das Ziel, die [Quellwert] bis [Quellwert] Feuerschaden verursacht. Wenn das Ziel von 'Flammenschock' betroffen ist, wird 'Lavaeruption' einen kritischen Treffer erzielen.", ["unresolvedValues"] = true }
entries[408491] = { ["name"] = "Lavaeruption", ["text"] = "30 Meter Reichweite\nSofort\nIhr schleudert flüssige Lava auf das Ziel, die [Quellwert] bis [Quellwert] Feuerschaden verursacht. Wenn das Ziel von 'Flammenschock' betroffen ist, wird 'Lavaeruption' einen kritischen Treffer erzielen.", ["unresolvedValues"] = true }
entries[408496] = { ["name"] = "Beidhändigkeitsspezialisierung", ["text"] = "Erhöht beim beidhändigen Führen Eure Chance, mit Zaubern und Nahkampfangriffen Treffer zu landen, um 5%. Außerdem trifft Eure Fähigkeit 'Sturmschlag' jetzt mit beiden Waffen, wenn Ihr beidhändig führt, und erhöht den verursachten Schaden Eurer Schildhandwaffe um 60%." }
entries[408498] = { ["name"] = "Waffe des Mahlstroms", ["text"] = "Wenn Ihr mit einem Nahkampfangriff Schaden verursacht, besteht eine Chance, dass die Zauberzeit und Manakosten Eures nächsten Einsatzes von 'Blitzschlag', 'Kettenblitzschlag', 'Geringe Welle der Heilung' oder 'Lavaeruption' um 20% verringert werden. Diese Chance ist um 50% erhöht, während Eure Waffenhandwaffe mit 'Waffe des Windzorns' belegt ist, und um weitere 50% erhöht, wenn Ihr eine Zweihandwaffe führt. Bis zu 5-mal stapelbar. Hält 30 Sek. lang an." }
entries[408501] = { ["name"] = "Mahlstrom bereit!" }
entries[408505] = { ["name"] = "Waffe des Mahlstroms", ["text"] = "Sofort\nVerringert die Zauberzeit und Manakosten Eures nächsten Wirkens von 'Blitzschlag', 'Kettenblitzschlag', 'Geringe Welle der Heilung' oder 'Lavaeruption' um 20%." }
entries[408507] = { ["name"] = "Lavapeitsche", ["text"] = "1% von Grundmana Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nLädt Eure Schildhandwaffe mit Lava auf, verursacht sofort 100% Waffenschaden der Schildhandwaffe. Der Schaden ist um 150% erhöht, wenn Eure Schildhandwaffe mit 'Flammenzunge' verzaubert ist." }
entries[408510] = { ["name"] = "Wasserschild", ["text"] = "Sofort\nDer Zaubernde wird von 3 Wasserkugeln umgeben, die alle 5 Sek. 1% Eures maximalen Manas gewähren. Trifft ein Zauber-, Nahkampf- oder Distanzangriff den Zaubernden, werden 4% seines maximalen Manas wiederhergestellt und eine Wasserkugel wird aufgelöst. Alle paar Sekunden kann nur eine Wasserkugel aktiviert werden. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n(3.5s Abklingzeit)" }
entries[408511] = { ["name"] = "Wasserschild", ["text"] = "Sofort\nErhält Mana durch erlittene Treffer, solange 'Wasserschild' aktiv ist." }
entries[408514] = { ["name"] = "Erdschild", ["text"] = "5% von Grundmana 40 Meter Reichweite\nSofort\nSchützt das Ziel mit einem Erdschild, der die Erhöhung der Zauberzeit oder Verringerung der Kanalisierungsdauer durch erlittenen Schaden um 30% verringert und Angriffe das geschützte Ziel um [Quellwert] Gesundheit heilen lässt. Dieser Effekt tritt nur einmal alle paar Sekunden auf. 9 Aufladungen. Hält 10 Min. lang an. Der Erdschild kann immer nur auf jeweils einem Ziel aktiv sein.\n(3.5s Abklingzeit)", ["unresolvedValues"] = true }
entries[408519] = { ["name"] = "Erdschild", ["text"] = "Unbegrenzte Reichweite\nSofort\nWird durch 'Erdschild' geheilt." }
entries[408521] = { ["name"] = "Springflut", ["text"] = "18% von Grundmana 40 Meter Reichweite\nSofort 6 sek. Abklingzeit\nHeilt ein verbündetes Ziel um [Quellwert] bis [Quellwert] Gesundheit und im Verlauf von 15 Sek. um weitere [Quellwert] Gesundheit. Wenn Ihr innerhalb von 15 Sek. 'Kettenheilung' auf dieses Hauptziel wirkt, wird die hervorgerufene Heilung um 25% erhöht. Dieser Zauber löst außerdem 'Erwachen der Ahnen' aus.", ["unresolvedValues"] = true }
entries[408524] = { ["name"] = "Schildmeisterschaft", ["text"] = "Jedes Mal, wenn Ihr blockt, regeneriert Ihr Mana in Höhe von 8% Eures maximalen Manas und erhaltet Rüstung in der Höhe von 30% des Rüstungswertes Eures Schildes. Bis zu 5-mal stapelbar. Ihr erhaltet außerdem immer eine um 10% erhöhte Blockchance und einen um 15% erhöhten Blockwert.\n\nAußerdem erhaltet Ihr immer, wenn Ihr eine Schockfähigkeit einsetzt, 4 Zauberschaden pro Punkt Eurer Verteidigungsfertigkeit, der über ( 60 * 5) hinausgeht. Hält 15 Sek. lang an." }
entries[408525] = { ["name"] = "Schildmeisterschaft", ["text"] = "Sofort\nErhöht die Rüstung 15 Sek. lang um 30% des Rüstungswertes Eures Schildes. Bis zu 7-mal stapelbar." }
entries[408531] = { ["name"] = "Weg der Erde", ["text"] = "Während 'Waffe des Felsbeißers' auf Eurer Waffenhand aktiv ist und Ihr einen Schild ausgerüstet habt, erzeugt Ihr 65% mehr Bedrohung, erhaltet 25% mehr Gesundheit, erleidet 10% weniger Schaden. Eure Chance, von Nahkampfangriffen kritisch getroffen zu werden, ist um 6% verringert. Euer 'Erdschock' verspottet Ziele, damit sie Euch angreifen, und hat eine von anderen Schockzaubern getrennte Abklingzeit, aber seine Reichweite wird auf Nahkampfreichweite verringert. Die Reichweite Eurer Zauber 'Blitzschlag', 'Kettenblitzschlag', 'Kettenheilung', 'Welle der Heilung' und 'Lavaeruption' ist jedoch um 20 Meter verringert." }
entries[408680] = { ["name"] = "Weg der Erde", ["text"] = "Sofort\nWährend 'Waffe des Felsbeißers' auf Eurer Waffenhand aktiv ist, verursacht Ihr 65% mehr Bedrohung, erhaltet 25% mehr Gesundheit, erleidet 10% weniger Schaden. Eure Chance, von Nahkampfangriffen kritisch getroffen zu werden, ist um 6% verringert. Euer 'Erdschock' verspottet Ziele, damit sie Euch angreifen, und hat eine von anderen Schockzaubern getrennte Abklingzeit." }
entries[408681] = { ["name"] = "Erdschock", ["text"] = "30 Mana Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nSchockt das Ziel unmittelbar mit erschütternder Kraft und verursacht 19 bis 22 Naturschaden. Unterbricht außerdem das Wirken von Zaubern und verhindert 2 Sek. lang, dass Zauber dieser Art gewirkt werden können. Verursacht ein hohes Maß an Bedrohung und verspottet das Ziel." }
entries[408683] = { ["name"] = "Erdschock", ["text"] = "50 Mana Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nSchockt das Ziel unmittelbar mit erschütternder Kraft und verursacht 35 bis 38 Naturschaden. Unterbricht außerdem das Wirken von Zaubern und verhindert 2 Sek. lang, dass Zauber dieser Art gewirkt werden können. Verursacht ein hohes Maß an Bedrohung und verspottet das Ziel." }
