entries[408689] = { ["name"] = "Erdschock", ["text"] = "345 Mana Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nSchockt das Ziel unmittelbar mit erschütternder Kraft und verursacht 372 bis 394 Naturschaden. Unterbricht außerdem das Wirken von Zaubern und verhindert 2 Sek. lang, dass Zauber dieser Art gewirkt werden können. Verursacht ein hohes Maß an Bedrohung und verspottet das Ziel." }
