entries[409324] = { ["name"] = "Führung der Ahnen", ["text"] = "Sofort 1 min Abklingzeit\nFür die nächsten 10 Sek. werden 25% Eures Schadens in Heilung für bis zu 3 Gruppenmitglieder in der Nähe umgewandelt. 100% Eurer Heilung werden in Schaden umgewandelt und dem letzten Ziel von Eurem 'Flammenschock' zugefügt." }
