entries[409379] = { ["name"] = "Tötungsbefehl", ["text"] = "1.5% von Grundmana 45 Meter Reichweite\nSofort 1 min Abklingzeit\nGibt Eurem Tier den Befehl zu töten. Erhöht den Schaden, den Euer Tier mit 'Klaue' und 'Beißen' verursacht, 30 Sek. lang um 60%. Mit jedem Einsatz von 'Klaue' oder 'Beißen' des Tieres sinkt der Schadensbonus um 20%." }
