entries[409433] = { ["name"] = "Schimärenschuss", ["text"] = "6% von Grundmana 8 - 35 Meter Reichweite\n6 sek. Abklingzeit\nBenötigt Distanzwaffe\nVerursacht 135% Waffenschaden, erneuert die Dauer des auf das Ziel wirkenden Stiches oder Bisses und löst einen Effekt aus:\n\nSchlangenbiss - Verursacht sofort 48% des von Eurem Schlangenbiss verursachten Schadens.\n\nVipernbiss - Stellt sofort 60% des von Eurem Vipernbiss abgezogenen Manas bei Euch wieder her.\n\nSkorpidstich - Versucht, das Ziel 10 Sek. lang zu entwaffnen. Dieser Effekt kann nur einmal pro Minute auftreten." }
entries[409493] = { ["name"] = "Schimärenschuss - Schlange", ["text"] = "100 Meter Reichweite\nVerursacht 135% Waffenschaden, erneuert die Dauer des auf das Ziel wirkenden Stiches oder Bisses und löst einen Effekt aus:\n\nSchlangenbiss - Verursacht sofort 48% des von Eurem 'Schlangenbiss' verursachten Schadens.\n\nVipernbiss - Stellt sofort 60% des von Eurem 'Vipernbiss' aufgebrauchten Manas bei Euch wieder her.\n\nSkorpidstich - Versucht, das Ziel 10 Sek. lang zu entwaffnen. Dieser Effekt kann nur einmal pro Minute auftreten." }
