entries[409510] = { ["name"] = "Eiskältefalle", ["text"] = "50 Mana 35 Meter Reichweite\n15 sek. Abklingzeit\nPlatziert eine Frostfalle in der Nähe, die den ersten sich nähernden Gegner einfriert und bis zu 10 Sek. lang alle Aktionen verhindert. Jeglicher verursachte Schaden wird das Eis brechen. Die Falle bleibt 1 Min. lang bestehen. Es kann immer nur eine Falle aktiv sein." }
entries[409512] = { ["name"] = "Eiskältefalle", ["text"] = "75 Mana 35 Meter Reichweite\n15 sek. Abklingzeit\nPlatziert eine Frostfalle in der Nähe, die den ersten sich nähernden Gegner einfriert und bis zu 15 Sek. lang alle Aktionen verhindert. Jeglicher verursachte Schaden wird das Eis brechen. Die Falle bleibt 1 Min. lang bestehen. Es kann immer nur eine Falle aktiv sein." }
entries[409519] = { ["name"] = "Eiskältefalle", ["text"] = "100 Mana 35 Meter Reichweite\n15 sek. Abklingzeit\nPlatziert eine Frostfalle in der Nähe, die den ersten sich nähernden Gegner einfriert und bis zu 20 Sek. lang alle Aktionen verhindert. Jeglicher verursachte Schaden wird das Eis brechen. Die Falle bleibt 1 Min. lang bestehen. Es kann immer nur eine Falle aktiv sein." }
entries[409520] = { ["name"] = "Frostfalle", ["text"] = "60 Mana\nSofort 15 sek. Abklingzeit\nPlatziert eine Frostfalle in der Nähe, die 30 Sek. lang um sich herum eine Eisfläche bildet, sobald der erste Gegner sich ihr nähert. Die Bewegungsgeschwindigkeit aller Gegner in einem Umkreis von 10 Metern wird um 60% verringert, solange sie sich im Wirkungsbereich befinden. Die Falle bleibt 1 Min. lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
