entries[409530] = { ["name"] = "Feuerbrandfalle", ["text"] = "245 Mana 35 Meter Reichweite\n15 sek. Abklingzeit\nPlatziert eine Feuerfalle in der Nähe, die dem ersten sich nähernden Gegner im Verlauf von 15 Sek. 690 Feuerschaden zufügt. Die Falle bleibt 1 Min. lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[409532] = { ["name"] = "Sprengfalle", ["text"] = "275 Mana 35 Meter Reichweite\n15 sek. Abklingzeit\nPlatziert eine Feuerfalle in der Nähe, die explodiert, wenn sich ein Gegner nähert. Die Falle verursacht 104 bis 135 Feuerschaden und fügt allen Zielen in einem Umkreis von 10 Metern im Verlauf von 20 Sek. zusätzlich 150 Feuerschaden zu. Die Falle bleibt 1 Min. lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
