entries[409541] = { ["name"] = "Fallenschleuder", ["text"] = "Eure Eiskältefallen, Feuerbrandfallen und Sprengfallen können jetzt an jedem Ort innerhalb von 35 Metern ausgelegt werden. Außerdem haben Eure feuer- und frostbasierten Fallen jetzt getrennte gemeinsame Abklingzeiten." }
entries[409552] = { ["name"] = "Explosivschuss", ["text"] = "3.5% von Grundmana 8 - 35 Meter Reichweite\n6 sek. Abklingzeit\nBenötigt Distanzwaffe\nFeuert ein Explosivgeschoss in das gegnerische Ziel, das allen Gegnern innerhalb von 8 Metern [Fernkampfangriffskraft * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] bis [Fernkampfangriffskraft * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] Feuerschaden zufügt. Die Sprengladung verursacht 2 Sek. lang pro Sekunde weiteren Schaden." }
entries[409554] = { ["name"] = "Explosivschuss", ["text"] = "Unbegrenzte Reichweite\nFeuert ein Explosivgeschoss, das dem gegnerischen Ziel (Fernkampfangriffskraft * 0.14 + 10) bis (Fernkampfangriffskraft * 0.14 + 10) Feuerschaden zufügt. Die Sprengladungen verursachen bis Abbruch lang pro Sekunde weiteren Schaden. Teilt sich die Abklingzeit mit 'Arkaner Schuss'." }
