entries[409593] = { ["name"] = "Tödlicher Schuss", ["text"] = "3% von Grundmana 35 Meter Reichweite\n12 sek. Abklingzeit\nBenötigt Distanzwaffe\nIhr versucht, ein verletztes Ziel mit einem Distanzangriff zu töten, der 100% Waffenschaden plus [Quellwert] verursacht. 'Tödlicher Schuss' hat keine Minimaldistanz, und seine Abklingzeit wird zurückgesetzt, wenn er gegen einen Gegner mit 20% oder weniger Gesundheit eingesetzt wird.", ["unresolvedValues"] = true }
