entries[409750] = { ["name"] = "Raptorstoß", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nEin heftiger Angriff, der den Nahkampfschaden um 17 erhöht." }
entries[409751] = { ["name"] = "Raptorstoß", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nEin heftiger Angriff, der den Nahkampfschaden um 25 erhöht." }
entries[409752] = { ["name"] = "Raptorstoß", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nEin heftiger Angriff, der den Nahkampfschaden um 40 erhöht." }
entries[409754] = { ["name"] = "Raptorstoß", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nEin heftiger Angriff, der den Nahkampfschaden um 55 erhöht." }
entries[409755] = { ["name"] = "Raptorstoß", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nEin heftiger Angriff, der den Nahkampfschaden um 70 erhöht." }
entries[409805] = { ["name"] = "Wilde Stöße", ["text"] = "Erhaltet die Fähigkeit 'Wilde Stöße':\n\nWährend Ihr in Katzengestalt, Bärengestalt oder Terrorbärengestalt seid, erlangen Gruppen- oder Schlachtzugsmitglieder im Umkreis von 100 Metern erhöhte Kampfwildheit. Bei jedem Nahkampftreffer besteht eine Chance von 20%, dem Angreifer einen Zusatzangriff mit 20% höherer Angriffskraft zu gewähren. Kein Effekt, wenn das Ziel bereits vom Totem des Windzorns profitiert." }
entries[409809] = { ["name"] = "Überlebensinstinkte", ["text"] = "Erhaltet die Fähigkeit 'Überlebensinstinkte':\n\nNach Aktivierung erhaltet Ihr 20 Sek. lang 30% Eurer maximalen Gesundheit. Während dieser Zeit wird zudem sämtliche von Euch hervorgerufene nichtkörperliche Heilung um 20% erhöht. Nachdem der Effekt abgelaufen ist, geht die Gesundheit verloren. Kann in jeder Gestalt mit Ausnahme der Moonkingestalt eingesetzt werden.\n\nZusätzlich regeneriert Ihr bei jedem Ausweichen in Bärengestalt oder Terrorbärengestalt 5 Wut, in Katzengestalt 10 Energie oder in jeder anderen Gestalt 1% Eures maximalen Manas." }
entries[409810] = { ["name"] = "Wildwuchs", ["text"] = "Erhaltet die Fähigkeit 'Wildwuchs':\n\nHeilt alle Gruppenmitglieder des anvisierten Spielercharakters innerhalb von 43.5 Metern um ihn herum im Verlauf von 7 Sek. um [Quellwert] Gesundheit. Die Heilung wird zunächst schnell und mit zunehmender Dauer von 'Wildwuchs' langsamer angewendet.", ["unresolvedValues"] = true }
entries[409813] = { ["name"] = "Finsternis", ["text"] = "Erhaltet die Fähigkeit 'Finsternis':\n\n'Sternenfeuer' erhöht die Chance auf kritische Treffer bei Euren nächsten beiden Einsätzen von 'Zorn' um 30%, und 'Zorn' verringert die Zauberzeit Eures nächsten Einsatzes von 'Sternenfeuer' um 1.0 Sek. Beide Effekte lassen sich bis zu 4-mal stapeln. Bei beiden Zaubern besteht außerdem jederzeit eine Chance von 70%, dass Ihr keine Zauberzeit verliert, wenn Ihr Schaden erleidet." }
entries[409819] = { ["name"] = "Wildes Brüllen", ["text"] = "Erhaltet die Fähigkeit 'Wildes Brüllen':\n\nFinishing-Move, der den verursachten körperlichen Schaden in Katzengestalt um 30% erhöht. Hält pro Combopunkt länger an:\n1 Punkt: 14 Sek.\n2 Punkte: 19 Sek.\n3 Punkte: 24 Sek.\n4 Punkte: 29 Sek.\n5 Punkte: 34 Sek." }
entries[409824] = { ["name"] = "Blühendes Leben", ["text"] = "Verringert die globale Abklingzeit Eurer Fähigkeiten 'Verjüngung' und 'Blühendes Leben' um 0.5 Sek. und Ihr erhaltet die Fähigkeit 'Blühendes Leben':\n\nHeilt das Ziel im Verlauf von 7 Sek. um [Quellwert] Gesundheit. Wenn 'Blühendes Leben' endet oder gebannt wird, wird das Ziel sofort um [Quellwert] Gesundheit geheilt und der Druide erhält die Hälfte der Zauberkosten erstattet. Dieser Effekt ist bis zu 3-mal auf einem Ziel stapelbar.", ["unresolvedValues"] = true }
entries[409826] = { ["name"] = "Zorn der Natur", ["text"] = "Erhaltet die Fähigkeit 'Zorn der Natur':\n\nErhöht Eure Heilkraft 30 Sek. lang um 90% Eures Naturzauberschadens." }
entries[409828] = { ["name"] = "Zerfleischen", ["text"] = "Erhaltet die Fähigkeit 'Zerfleischen (Bär)' und ersetzt Eure Fähigkeit 'Klaue' mit 'Zerfleischen (Katze). Diese Fähigkeit profitiert von allen Effekten von 'Klaue' und 'Zermalmen' und löst diese aus.\n\nZerfleischt das Ziel, fügt ihm 160% des normalen Schadens zu und lässt es 1 Min. lang 30% zusätzlichen Schaden durch Blutungseffekte und 'Schreddern' erleiden. Diese Fähigkeit profitiert von allen Effekten von 'Klaue' und 'Zermalmen' und löst diese aus.\n\nWenn Ihr ein Ziel mit 'Zerfleischen (Bär)' trefft, erhaltet Ihr zudem 4 Angriffskraft für jeden Punkt Eurer Verteidigungsfertigkeit über ( 60 * 5). Hält 15 Sek. lang an.\n\nZerfleischt das Ziel, fügt ihm 270% des normalen Schadens zu und lässt es 1 Min. lang 30% zusätzlichen Schaden durch Blutungseffekte und 'Schreddern' erleiden. Gewährt 1 Combopunkt. Diese Fähigkeit profitiert von allen Effekten von 'Klaue' und 'Zermalmen' und löst diese aus." }
entries[409830] = { ["name"] = "Pflege", ["text"] = "Erhaltet die Fähigkeit 'Pflege':\n\nHeilt ein verbündetes Ziel um [Quellwert] bis [Quellwert] Gesundheit. Wenn ein durch Euch gewirkter Effekt von 'Verjüngung', 'Nachwachsen', 'Wildwuchs' oder 'Blühendes Leben' auf dem Ziel aktiv ist, erhöht sich die Heilung um zusätzliche 20%. Dieser Zauber profitiert von allen Effekten von 'Heilende Berührung' oder 'Nachwachsen' und löst diese aus.", ["unresolvedValues"] = true }
entries[409831] = { ["name"] = "Traumzustand", ["text"] = "Erhaltet die Fähigkeit 'Traumzustand':\n\nKritische Treffer Eurer nicht regelmäßigen Schadenszauber und jeglicher Schaden von Eurem 'Sternensog' gewähren Euch 8 Sek. lang 50% Manaregeneration, während Ihr Zauber wirkt. Der Arkan- und Naturschaden gegen Ziele, bei denen es sich nicht um Spielercharaktere handelt, wird außerdem 12 Sek. lang um 20% erhöht." }
entries[409832] = { ["name"] = "Furor von Sturmgrimm", ["text"] = "Erhaltet die Fähigkeit 'Furor von Sturmgrimm':\n\nVerringert die Manakosten von 'Zorn' um 100%. Jedes Mal, wenn Ihr Schaden mit 'Zorn' verursacht, besteht eine Chance von 12%, dass Eure nächste 'Heilende Berührung' innerhalb von 15 Sek. ein Spontanzauber ist und in allen Gestaltwandelgestalten einsetzbar ist. Erlaubt in Baum-des-Lebens-Gestalt 'Zorn' zu zaubern." }
entries[409856] = { ["name"] = "Geisterritual", ["text"] = "30 Meter Reichweite\nKanalisiert (Wirken in 10 min)\nBeginnt ein Ritual, um den Geist eines gefallenen Abenteurers zu befreien." }
entries[409858] = { ["name"] = "Dummy Trigger" }
entries[409906] = { ["name"] = "Flamme des Glaubens", ["text"] = "Erhaltet die Fähigkeit 'Flamme des Glaubens':\n\nDas Ziel wird für alle Gruppen- und Schlachtzugsmitglieder in einem Radius von 40 Metern zu einer Flamme des Glaubens. Alle auf diese Mitglieder gewirkten Heilungen heilen auch die Flamme um 75% der gewirkten Heilung. Es kann immer nur ein Ziel zur gleichen Zeit eine Flamme des Glaubens sein. Hält 1 Stunde lang an." }
entries[409911] = { ["name"] = "Hand der Abrechnung", ["text"] = "Erhaltet die Fähigkeit 'Hand der Abrechnung':\n\nVerspottet das Ziel, damit es Euch angreift. Hat keinen Effekt, wenn Ihr von dem Ziel bereits angegriffen werdet.\n\nWährend Ihr diese Fähigkeit kennt, ist der Bedrohungsbonus von 'Zorn der Gerechtigkeit' auf 80% erhöht. Wenn Ihr von anderen Charakteren geheilt werdet, sorgt 'Zorn der Gerechtigkeit' dafür, dass Ihr Mana in Höhe von 25% der hervorgerufenen Heilung erhaltet. Zusätzlich wird Schaden, der Eure Gesundheit unter 35% senkt, um 20% verringert, während 'Zorn der Gerechtigkeit' aktiv ist. 'Zorn der Gerechtigkeit' bleibt aktiv, bis er abgebrochen wird." }
entries[409914] = { ["name"] = "Kreuzfahrerstoß", ["text"] = "Erhaltet die Fähigkeit 'Kreuzfahrerstoß':\n\nEin sofortiger Stoß, der 75% Waffenschaden als Heiligschaden verursacht und 5% Eures maximalen Manas regeneriert. Die Dauer aller Richturteilseffekte auf dem Ziel wird auf 30 Sek. zurückgesetzt." }
entries[409918] = { ["name"] = "Inspiration (Richturteil)" }
entries[409920] = { ["name"] = "Relikt erlernen (Richturteil)" }
entries[409922] = { ["name"] = "Hammer der Rechtschaffenen", ["text"] = "Erhaltet die Fähigkeit 'Hammer der Rechtschaffenen':\n\nTrifft das aktuelle Ziel sowie bis zu 3 zusätzliche Ziele in der Nähe und verursacht pro Sekunde den 4-fachen Schaden Eurer Waffenhandwaffe als Heiligschaden." }
entries[409924] = { ["name"] = "Göttlicher Sturm", ["text"] = "Erhaltet die Fähigkeit 'Göttlicher Sturm':\n\nEin sofortiger Waffenangriff, der bis zu 4 Gegnern innerhalb von 8 Metern 110% Waffenschaden zufügt. 'Göttlicher Sturm' heilt bis zu 3 Gruppen- oder Schlachtzugsmitglieder in Höhe von 25% des verursachten Schadens." }
entries[409925] = { ["name"] = "Göttliches Licht" }
entries[409930] = { ["name"] = "Buchband des Richturteils" }
entries[409932] = { ["name"] = "Aurenmeisterschaft", ["text"] = "Erhaltet die Fähigkeit 'Aurenmeisterschaft':\n\nVerleiht allen durch Eure Fähigkeit 'Aura der Konzentration' gestärkten Zielen Immunität gegen Unterbrechungs- und Stilleeffekte. Die Effekte aller anderen Auren werden um 100% erhöht. Hält 6 Sek. lang an." }
entries[409933] = { ["name"] = "Schild des Rächers", ["text"] = "Erhaltet die Fähigkeit 'Schild des Rächers':\n\nSchleudert einen heiligen Schild auf den Gegner, der [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Zaubermacht + 0.091 * Angriffskraft] bis [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Zaubermacht + 0.091 * Angriffskraft] Heiligschaden verursacht, ihn benommen macht und dann auf weitere Gegner in der Nähe überspringt. Wirkt auf insgesamt 3 Ziele. Hält 5 Sek. lang an." }
entries[409934] = { ["name"] = "Zornige Vergeltung", ["text"] = "Erhaltet die Fähigkeit 'Zornige Vergeltung':\n\nErhöht 20 Sek. lang jeglichen verursachten Schaden und Heilung um 20%. Verursacht 'Vorahnung' und kann nicht eingesetzt werden, während 'Vorahnung' aktiv ist." }
entries[409935] = { ["name"] = "Hand der Aufopferung", ["text"] = "Erhaltet die Fähigkeit 'Hand der Aufopferung':\n\nLässt das anvisierte Gruppen- oder Schlachtzugsmitglied pro Treffer 30% des erlittenen Schadens auf den Zaubernden übertragen. Hält 12 Sek. lang an oder bis Schaden in Höhe von 100% der maximalen Gesundheit des Zaubernden übertragen wurde." }
entries[409936] = { ["name"] = "Inspirationsvorbild", ["text"] = "Erhaltet die Fähigkeit 'Inspirationsvorbild':\n\nEure inspirierende Präsenz bannt regelmäßig Furcht- und Schlafeffekte von Gruppenmitgliedern in der Nähe." }
entries[409938] = { ["name"] = "Feuernova", ["text"] = "Erhaltet die Fähigkeit 'Feuernova'. Ersetzt Euer Totem der Feuernova:\n\nEuer Totem der Feuernova wird durch 'Feuernova' ersetzt. Dadurch verursacht Euer derzeitiges Feuertotem Schaden an seinem Standort." }
entries[409940] = { ["name"] = "Beidhändigkeitsspezialisierung", ["text"] = "Erhaltet die Fähigkeit 'Beidhändigkeitsspezialisierung':\n\nErhöht beim beidhändigen Führen Eure Chance, mit Zaubern und Nahkampfangriffen Treffer zu landen, um 5%. Außerdem trifft Eure Fähigkeit 'Sturmschlag' jetzt mit beiden Waffen, wenn Ihr beidhändig führt, und erhöht den verursachten Schaden Eurer Schildhandwaffe um 60%." }
entries[409941] = { ["name"] = "Wasserschild", ["text"] = "Erhaltet die Fähigkeit 'Wasserschild':\n\nDer Zaubernde wird von 3 Wasserkugeln umgeben, die alle 5 Sek. 1% Eures maximalen Manas gewähren. Trifft ein Zauber-, Nahkampf- oder Distanzangriff den Zaubernden, werden 4% seines maximalen Manas wiederhergestellt und eine Wasserkugel wird aufgelöst. Alle paar Sekunden kann nur eine Wasserkugel aktiviert werden. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein." }
entries[409943] = { ["name"] = "Schildmeisterschaft", ["text"] = "Erhaltet die Fähigkeit 'Schildmeisterschaft':\n\nJedes Mal, wenn Ihr blockt, regeneriert Ihr Mana in Höhe von 8% Eures maximalen Manas und erhaltet Rüstung in der Höhe von 30% des Rüstungswertes Eures Schildes. Bis zu 5-mal stapelbar. Ihr erhaltet außerdem immer eine um 10% erhöhte Blockchance und einen um 15% erhöhten Blockwert.\n\nAußerdem erhaltet Ihr immer, wenn Ihr eine Schockfähigkeit einsetzt, 4 Zauberschaden pro Punkt Eurer Verteidigungsfertigkeit, der über ( 60 * 5) hinausgeht. Hält 15 Sek. lang an." }
entries[409944] = { ["name"] = "Führung der Ahnen", ["text"] = "Erhaltet die Fähigkeit 'Führung der Ahnen':\n\nFür die nächsten 10 Sek. werden 25% Eures Schadens in Heilung für bis zu 3 Gruppenmitglieder in der Nähe umgewandelt. 100% Eurer Heilung werden in Schaden umgewandelt und dem letzten Ziel von Eurem 'Flammenschock' zugefügt." }
entries[409945] = { ["name"] = "Überladung", ["text"] = "Erhaltet die Fähigkeit 'Überladung!':\n\nVerleiht Euren Zaubern 'Blitzschlag', 'Kettenblitzschlag', 'Kettenheilung', 'Welle der Heilung' und 'Lavaeruption' eine Chance von 60%, kostenlos einen zweiten, ähnlichen Zauber auf das gleiche Ziel auszulösen. Dieser verursacht nur halben Schaden bzw. halbe Heilung und erzeugt keine Bedrohung." }
entries[409946] = { ["name"] = "Waffe des Mahlstroms", ["text"] = "Erhaltet die Fähigkeit 'Waffe des Mahlstroms':\n\nWenn Ihr mit einem Nahkampfangriff Schaden verursacht, besteht eine Chance, dass die Zauberzeit und Manakosten Eures nächsten Einsatzes von 'Blitzschlag', 'Kettenblitzschlag', 'Geringe Welle der Heilung' oder 'Lavaeruption' um 20% verringert werden. Diese Chance ist um 50% erhöht, während Eure Waffenhandwaffe mit 'Waffe des Windzorns' belegt ist, und um weitere 50% erhöht, wenn Ihr eine Zweihandwaffe führt. Bis zu 5-mal stapelbar. Hält 30 Sek. lang an." }
entries[409947] = { ["name"] = "Erdschild", ["text"] = "Erhaltet die Fähigkeit 'Erdschild':\n\nSchützt das Ziel mit einem Erdschild, der die Erhöhung der Zauberzeit oder Verringerung der Kanalisierungsdauer durch erlittenen Schaden um 30% verringert und Angriffe das geschützte Ziel um [Quellwert] Gesundheit heilen lässt. Dieser Effekt tritt nur einmal alle paar Sekunden auf. 9 Aufladungen. Hält 10 Min. lang an. Der Erdschild kann immer nur auf jeweils einem Ziel aktiv sein.", ["unresolvedValues"] = true }
entries[409951] = { ["name"] = "Geist des Alphas", ["text"] = "Erhaltet die Fähigkeit 'Geist des Alphas':\n\nErfüllt das Ziel mit dem Geist eines Alphawolfes, was die generierte Bedrohung des Ziels 30 Min. lang um 45% erhöht. Maximal 1 Ziel. Wenn der Schamane diesen Zauber nicht auf sich selbst wirkt, erhält er 'Treuer Beta', was 30 Min. lang seinen verursachten körperlichen Schaden um 5% erhöht und jegliche erzeugte Bedrohung um 30% verringert. Ein Ziel kann nicht gleichzeitig mit 'Geist des Alphas' und 'Treuer Beta' belegt sein." }
entries[409952] = { ["name"] = "Lavaeruption", ["text"] = "Erhaltet die Fähigkeit 'Lavaeruption':\n\nIhr schleudert flüssige Lava auf das Ziel, die [Quellwert] bis [Quellwert] Feuerschaden verursacht. Wenn das Ziel von 'Flammenschock' betroffen ist, wird 'Lavaeruption' einen kritischen Treffer erzielen.", ["unresolvedValues"] = true }
entries[409953] = { ["name"] = "Lavapeitsche", ["text"] = "Erhaltet die Fähigkeit 'Lavapeitsche':\n\nLädt Eure Schildhandwaffe mit Lava auf, verursacht sofort 100% Waffenschaden der Schildhandwaffe. Der Schaden ist um 150% erhöht, wenn Eure Schildhandwaffe mit 'Flammenzunge' verzaubert ist." }
entries[409954] = { ["name"] = "Springflut", ["text"] = "Erhaltet die Fähigkeit 'Springflut':\n\nHeilt ein verbündetes Ziel um [Quellwert] bis [Quellwert] Gesundheit und im Verlauf von 15 Sek. um weitere [Quellwert] Gesundheit. Wenn Ihr innerhalb von 15 Sek. 'Kettenheilung' auf dieses Hauptziel wirkt, wird die hervorgerufene Heilung um 25% erhöht. Dieser Zauber löst außerdem 'Erwachen der Ahnen' aus.", ["unresolvedValues"] = true }
entries[409955] = { ["name"] = "Weg der Erde", ["text"] = "Erhaltet die Fähigkeit 'Weg der Erde':\n\nWährend 'Waffe des Felsbeißers' auf Eurer Waffenhand aktiv ist und Ihr einen Schild ausgerüstet habt, erzeugt Ihr 65% mehr Bedrohung, erhaltet 25% mehr Gesundheit, erleidet 10% weniger Schaden. Eure Chance, von Nahkampfangriffen kritisch getroffen zu werden, ist um 6% verringert. Euer 'Erdschock' verspottet Ziele, damit sie Euch angreifen, und hat eine von anderen Schockzaubern getrennte Abklingzeit, aber seine Reichweite wird auf Nahkampfreichweite verringert. Die Reichweite Eurer Zauber 'Blitzschlag', 'Kettenblitzschlag', 'Kettenheilung', 'Welle der Heilung' und 'Lavaeruption' ist jedoch um 20 Meter verringert." }
entries[409957] = { ["name"] = "Zuverlässiger Schuss", ["text"] = "Erhaltet die Fähigkeit 'Zuverlässiger Schuss':\n\nEin zuverlässiger Schuss, der 100% Schaden mit Distanzwaffen verursacht." }
entries[409958] = { ["name"] = "Meister der Treffsicherheit", ["text"] = "Erhaltet die Fähigkeit 'Meister der Treffsicherheit':\n\nErhöht Eure kritische Trefferchance um 5% und verringert die Manakosten aller Eurer Schussfähigkeiten um 25%." }
entries[409959] = { ["name"] = "Schwäche aufdecken", ["text"] = "Erhaltet die Fähigkeit 'Schwäche aufdecken':\n\nEure kritischen Treffer mit Nahkampf- und Distanzangriffen erhöhen 7 Sek. lang Eure Angriffskraft um 40% Eurer aktuellen Beweglichkeit." }
entries[409960] = { ["name"] = "Kobraschlächter", ["text"] = "Erhaltet die Fähigkeit 'Kobraschlächter':\n\n'Mungobiss' hat bei jedem Eurer Nahkampfangriffe eine Chance von 10%, aktiviert zu werden, sowie eine Chance von 100%, wenn der Gegner ausweicht. Diese Chance sammelt sich an und steigt durch jeden Angriff in Folge, bei dem sie nicht zurückgesetzt wird, um 10%. 'Mungobiss' verursacht zusätzlichen Schaden in Höhe von 45% Eurer Angriffskraft." }
entries[409961] = { ["name"] = "Beidhändigkeitsspezialisierung", ["text"] = "Erhaltet die Fähigkeit 'Beidhändigkeitsspezialisierung':\n\nErhöht den von Eurer Schildhandwaffe verursachten Schaden um 60% und führt dazu, dass Euer 'Raptorstoß' mit beiden Waffen trifft, wenn Ihr beidhändig kämpft." }
entries[409962] = { ["name"] = "Meister der Tiere", ["text"] = "Erhaltet die Fähigkeit 'Meister der Tiere':\n\nErhöht Schaden und Gesundheit Eures Tiers um 15% und seine Fokusregeneration um 50%. Außerdem verspottet das 'Knurren' Eures Tiers das Ziel 3 Sek. lang." }
entries[409963] = { ["name"] = "Geist beschwören" }
entries[409968] = { ["name"] = "Fallenschleuder", ["text"] = "Erhaltet die Fähigkeit 'Fallenschleuder':\n\nEure Eiskältefallen, Feuerbrandfallen und Sprengfallen können jetzt an jedem Ort innerhalb von 35 Metern ausgelegt werden. Außerdem haben Eure feuer- und frostbasierten Fallen jetzt getrennte gemeinsame Abklingzeiten." }
entries[409974] = { ["name"] = "Tödlicher Schuss", ["text"] = "Erhaltet die Fähigkeit 'Tödlicher Schuss':\n\nIhr versucht, ein verletztes Ziel mit einem Distanzangriff zu töten, der 100% Waffenschaden plus [Quellwert] verursacht. 'Tödlicher Schuss' hat keine Minimaldistanz, und seine Abklingzeit wird zurückgesetzt, wenn er gegen einen Gegner mit 20% oder weniger Gesundheit eingesetzt wird.", ["unresolvedValues"] = true }
entries[409976] = { ["name"] = "Schimärenschuss", ["text"] = "Erhaltet die Fähigkeit 'Schimärenschuss':\n\nVerursacht 135% Waffenschaden, erneuert die Dauer des auf das Ziel wirkenden Stiches oder Bisses und löst einen Effekt aus:\n\nSchlangenbiss - Verursacht sofort 48% des von Eurem Schlangenbiss verursachten Schadens.\n\nVipernbiss - Stellt sofort 60% des von Eurem Vipernbiss abgezogenen Manas bei Euch wieder her.\n\nSkorpidstich - Versucht, das Ziel 10 Sek. lang zu entwaffnen. Dieser Effekt kann nur einmal pro Minute auftreten." }
entries[409978] = { ["name"] = "Explosivschuss", ["text"] = "Erhaltet die Fähigkeit 'Explosivschuss':\n\nFeuert ein Explosivgeschoss in das gegnerische Ziel, das allen Gegnern innerhalb von 8 Metern [Fernkampfangriffskraft * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] bis [Fernkampfangriffskraft * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] Feuerschaden zufügt. Die Sprengladung verursacht 2 Sek. lang pro Sekunde weiteren Schaden." }
entries[409979] = { ["name"] = "Einsamer Wolf", ["text"] = "Erhaltet die Fähigkeit 'Einsamer Wolf':\n\nIhr verursacht mit allen Angriffen 25% mehr Schaden, während Ihr kein Tier aktiviert habt." }
entries[409988] = { ["name"] = "Spielercharakter zum Wirken von 'Verzögerte Verbannung' zwingen" }
entries[409999] = { ["name"] = "Handschuhe prägen - Flamme des Glaubens", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Flamme des Glaubens':\n\nDas Ziel wird für alle Gruppen- und Schlachtzugsmitglieder in einem Radius von 40 Metern zu einer Flamme des Glaubens. Alle auf diese Mitglieder gewirkten Heilungen heilen auch die Flamme um 75% der gewirkten Heilung. Es kann immer nur ein Ziel zur gleichen Zeit eine Flamme des Glaubens sein. Hält 1 Stunde lang an." }
entries[410001] = { ["name"] = "Handschuhe prägen - Hand der Abrechnung", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Hand der Abrechnung':\n\nVerspottet das Ziel, damit es Euch angreift. Hat keinen Effekt, wenn Ihr von dem Ziel bereits angegriffen werdet.\n\nWährend Ihr diese Fähigkeit kennt, ist der Bedrohungsbonus von 'Zorn der Gerechtigkeit' auf 80% erhöht. Wenn Ihr von anderen Charakteren geheilt werdet, sorgt 'Zorn der Gerechtigkeit' dafür, dass Ihr Mana in Höhe von 25% der hervorgerufenen Heilung erhaltet. Zusätzlich wird Schaden, der Eure Gesundheit unter 35% senkt, um 20% verringert, während 'Zorn der Gerechtigkeit' aktiv ist. 'Zorn der Gerechtigkeit' bleibt aktiv, bis er abgebrochen wird." }
entries[410002] = { ["name"] = "Handschuhe prägen - Kreuzfahrerstoß", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Kreuzfahrerstoß':\n\nEin sofortiger Stoß, der 75% Waffenschaden als Heiligschaden verursacht und 5% Eures maximalen Manas regeneriert. Die Dauer aller Richturteilseffekte auf dem Ziel wird auf 30 Sek. zurückgesetzt." }
entries[410005] = { ["name"] = "Hosen prägen - Aurenmeisterschaft", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Aurenmeisterschaft':\n\nVerleiht allen durch Eure Fähigkeit 'Aura der Konzentration' gestärkten Zielen Immunität gegen Unterbrechungs- und Stilleeffekte. Die Effekte aller anderen Auren werden um 100% erhöht. Hält 6 Sek. lang an." }
entries[410008] = { ["name"] = "Hosen prägen - Schild des Rächers", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Schild des Rächers':\n\nSchleudert einen heiligen Schild auf den Gegner, der [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Zaubermacht + 0.091 * Angriffskraft] bis [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Zaubermacht + 0.091 * Angriffskraft] Heiligschaden verursacht, ihn benommen macht und dann auf weitere Gegner in der Nähe überspringt. Wirkt auf insgesamt 3 Ziele. Hält 5 Sek. lang an." }
entries[410010] = { ["name"] = "Hosen prägen - Hand der Aufopferung", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Hand der Aufopferung':\n\nLässt das anvisierte Gruppen- oder Schlachtzugsmitglied pro Treffer 30% des erlittenen Schadens auf den Zaubernden übertragen. Hält 12 Sek. lang an oder bis Schaden in Höhe von 100% der maximalen Gesundheit des Zaubernden übertragen wurde." }
entries[410011] = { ["name"] = "Hosen prägen - Inspirationsvorbild", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Inspirationsvorbild':\n\nEure inspirierende Präsenz bannt regelmäßig Furcht- und Schlafeffekte von Gruppenmitgliedern in der Nähe." }
entries[410013] = { ["name"] = "Armschienen prägen - Hammer der Rechtschaffenen", ["text"] = "Wirken in 3 sek.\nBenötigt Armschienen\nPrägt Eure Armschienen mit der Rune 'Hammer der Rechtschaffenen':\n\nTrifft das aktuelle Ziel sowie bis zu 3 zusätzliche Ziele in der Nähe und verursacht pro Sekunde den 4-fachen Schaden Eurer Waffenhandwaffe als Heiligschaden." }
entries[410014] = { ["name"] = "Brustteil prägen - Göttlicher Sturm", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil mit der Rune 'Göttlicher Sturm':\n\nEin sofortiger Waffenangriff, der bis zu 4 Gegnern innerhalb von 8 Metern 110% Waffenschaden zufügt. 'Göttlicher Sturm' heilt bis zu 3 Gruppen- oder Schlachtzugsmitglieder in Höhe von 25% des verursachten Schadens." }
entries[410015] = { ["name"] = "Umhang prägen - Göttliches Licht", ["text"] = "Wirken in 3 sek.\nBenötigt Umhang" }
entries[410021] = { ["name"] = "Brustteil prägen - Wilde Stöße", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Wilde Stöße':\n\nWährend Ihr in Katzengestalt, Bärengestalt oder Terrorbärengestalt seid, erlangen Gruppen- oder Schlachtzugsmitglieder im Umkreis von 100 Metern erhöhte Kampfwildheit. Bei jedem Nahkampftreffer besteht eine Chance von 20%, dem Angreifer einen Zusatzangriff mit 20% höherer Angriffskraft zu gewähren. Kein Effekt, wenn das Ziel bereits vom Totem des Windzorns profitiert." }
entries[410023] = { ["name"] = "Hosen prägen - Wildes Brüllen", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Wildes Brüllen':\n\nFinishing-Move, der den verursachten körperlichen Schaden in Katzengestalt um 30% erhöht. Hält pro Combopunkt länger an:\n1 Punkt: 14 Sek.\n2 Punkte: 19 Sek.\n3 Punkte: 24 Sek.\n4 Punkte: 29 Sek.\n5 Punkte: 34 Sek." }
entries[410025] = { ["name"] = "Handschuhe prägen - Zerfleischen", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Zerfleischen':\n\nZerfleischt das Ziel, fügt ihm 160% des normalen Schadens zu und lässt es 1 Min. lang 30% zusätzlichen Schaden durch Blutungseffekte und 'Schreddern' erleiden. Diese Fähigkeit profitiert von allen Effekten von 'Klaue' und 'Zermalmen' und löst diese aus.\n\nWenn Ihr ein Ziel mit 'Zerfleischen (Bär)' trefft, erhaltet Ihr zudem 4 Angriffskraft für jeden Punkt Eurer Verteidigungsfertigkeit über ( 60 * 5). Hält 15 Sek. lang an." }
entries[410027] = { ["name"] = "Stiefel prägen - Überlebensinstinkte", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel\nPrägt Eure Stiefel mit der Rune 'Überlebensinstinkte':\n\nNach Aktivierung erhaltet Ihr 20 Sek. lang 30% Eurer maximalen Gesundheit. Während dieser Zeit wird zudem sämtliche von Euch hervorgerufene nichtkörperliche Heilung um 20% erhöht. Nachdem der Effekt abgelaufen ist, geht die Gesundheit verloren. Kann in jeder Gestalt mit Ausnahme der Moonkingestalt eingesetzt werden.\n\nZusätzlich regeneriert Ihr bei jedem Ausweichen in Bärengestalt oder Terrorbärengestalt 5 Wut, in Katzengestalt 10 Energie oder in jeder anderen Gestalt 1% Eures maximalen Manas." }
entries[410028] = { ["name"] = "Handschuhe prägen - Wildwuchs", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Wildwuchs':\n\nHeilt alle Gruppenmitglieder des anvisierten Spielercharakters innerhalb von 43.5 Metern um ihn herum im Verlauf von 7 Sek. um [Quellwert] Gesundheit. Die Heilung wird zunächst schnell und mit zunehmender Dauer von 'Wildwuchs' langsamer angewendet.", ["unresolvedValues"] = true }
entries[410029] = { ["name"] = "Gürtel prägen - Finsternis", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Finsternis':\n\n'Sternenfeuer' erhöht die Chance auf kritische Treffer bei Euren nächsten beiden Einsätzen von 'Zorn' um 30%, und 'Zorn' verringert die Zauberzeit Eures nächsten Einsatzes von 'Sternenfeuer' um 1.0 Sek. Beide Effekte lassen sich bis zu 4-mal stapeln. Bei beiden Zaubern besteht außerdem jederzeit eine Chance von 70%, dass Ihr keine Zauberzeit verliert, wenn Ihr Schaden erleidet." }
entries[410033] = { ["name"] = "Hosen prägen - Blühendes Leben", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Blühendes Leben':\n\nVerringert die globale Abklingzeit Eurer Fähigkeiten 'Verjüngung' und 'Blühendes Leben' um 0.5 Sek. und Ihr erhaltet die Fähigkeit 'Blühendes Leben':\n\nHeilt das Ziel im Verlauf von 7 Sek. um [Quellwert] Gesundheit. Wenn 'Blühendes Leben' endet oder gebannt wird, wird das Ziel sofort um [Quellwert] Gesundheit geheilt und der Druide erhält die Hälfte der Zauberkosten erstattet. Dieser Effekt ist bis zu 3-mal auf einem Ziel stapelbar.", ["unresolvedValues"] = true }
entries[410059] = { ["name"] = "Gürtel prägen - Pflege", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Pflege':\n\nHeilt ein verbündetes Ziel um [Quellwert] bis [Quellwert] Gesundheit. Wenn ein durch Euch gewirkter Effekt von 'Verjüngung', 'Nachwachsen', 'Wildwuchs' oder 'Blühendes Leben' auf dem Ziel aktiv ist, erhöht sich die Heilung um zusätzliche 20%. Dieser Zauber profitiert von allen Effekten von 'Heilende Berührung' oder 'Nachwachsen' und löst diese aus.", ["unresolvedValues"] = true }
entries[410060] = { ["name"] = "Stiefel prägen - Traumzustand", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel\nPrägt Eure Stiefel mit der Rune 'Traumzustand':\n\nKritische Treffer Eurer nicht regelmäßigen Schadenszauber und jeglicher Schaden von Eurem 'Sternensog' gewähren Euch 8 Sek. lang 50% Manaregeneration, während Ihr Zauber wirkt. Der Arkan- und Naturschaden gegen Ziele, bei denen es sich nicht um Spielercharaktere handelt, wird außerdem 12 Sek. lang um 20% erhöht." }
entries[410061] = { ["name"] = "Brustteil prägen - Furor von Sturmgrimm", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Furor von Sturmgrimm':\n\nVerringert die Manakosten von 'Zorn' um 100%. Jedes Mal, wenn Ihr Schaden mit 'Zorn' verursacht, besteht eine Chance von 12%, dass Eure nächste 'Heilende Berührung' innerhalb von 15 Sek. ein Spontanzauber ist und in allen Gestaltwandelgestalten einsetzbar ist. Erlaubt in Baum-des-Lebens-Gestalt 'Zorn' zu zaubern." }
entries[410093] = { ["name"] = "Gürtel prägen - Feuernova", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Feuernova':\n\nEuer Totem der Feuernova wird durch 'Feuernova' ersetzt. Dadurch verursacht Euer derzeitiges Feuertotem Schaden an seinem Standort." }
entries[410094] = { ["name"] = "Brustteil prägen - Überladung", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Überladung':\n\nVerleiht Euren Zaubern 'Blitzschlag', 'Kettenblitzschlag', 'Kettenheilung', 'Welle der Heilung' und 'Lavaeruption' eine Chance von 60%, kostenlos einen zweiten, ähnlichen Zauber auf das gleiche Ziel auszulösen. Dieser verursacht nur halben Schaden bzw. halbe Heilung und erzeugt keine Bedrohung." }
entries[410095] = { ["name"] = "Handschuhe prägen - Lavaeruption", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Lavaeruption':\n\nIhr schleudert flüssige Lava auf das Ziel, die [Quellwert] bis [Quellwert] Feuerschaden verursacht. Wenn das Ziel von 'Flammenschock' betroffen ist, wird 'Lavaeruption' einen kritischen Treffer erzielen.", ["unresolvedValues"] = true }
entries[410096] = { ["name"] = "Brustteil prägen - Beidhändigkeitsspezialisierung", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Beidhändigkeitsspezialisierung':\n\nErhöht beim beidhändigen Führen Eure Chance, mit Zaubern und Nahkampfangriffen Treffer zu landen, um 5%. Außerdem trifft Eure Fähigkeit 'Sturmschlag' jetzt mit beiden Waffen, wenn Ihr beidhändig führt, und erhöht den verursachten Schaden Eurer Schildhandwaffe um 60%." }
entries[410097] = { ["name"] = "Handschuhe prägen - Wasserschild", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Wasserschild':\n\nDer Zaubernde wird von 3 Wasserkugeln umgeben, die alle 5 Sek. 1% Eures maximalen Manas gewähren. Trifft ein Zauber-, Nahkampf- oder Distanzangriff den Zaubernden, werden 4% seines maximalen Manas wiederhergestellt und eine Wasserkugel wird aufgelöst. Alle paar Sekunden kann nur eine Wasserkugel aktiviert werden. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein." }
entries[410098] = { ["name"] = "Brustteil prägen - Schildmeisterschaft", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Schildmeisterschaft':\n\nJedes Mal, wenn Ihr blockt, regeneriert Ihr Mana in Höhe von 8% Eures maximalen Manas und erhaltet Rüstung in der Höhe von 30% des Rüstungswertes Eures Schildes. Bis zu 5-mal stapelbar. Ihr erhaltet außerdem immer eine um 10% erhöhte Blockchance und einen um 15% erhöhten Blockwert.\n\nAußerdem erhaltet Ihr immer, wenn Ihr eine Schockfähigkeit einsetzt, 4 Zauberschaden pro Punkt Eurer Verteidigungsfertigkeit, der über ( 60 * 5) hinausgeht. Hält 15 Sek. lang an." }
entries[410099] = { ["name"] = "Hosen prägen - Führung der Ahnen", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Führung der Ahnen':\n\nFür die nächsten 10 Sek. werden 25% Eures Schadens in Heilung für bis zu 3 Gruppenmitglieder in der Nähe umgewandelt. 100% Eurer Heilung werden in Schaden umgewandelt und dem letzten Ziel von Eurem 'Flammenschock' zugefügt." }
entries[410100] = { ["name"] = "Gürtel prägen - Waffe des Mahlstroms", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Waffe des Mahlstroms':\n\nWenn Ihr mit einem Nahkampfangriff Schaden verursacht, besteht eine Chance, dass die Zauberzeit und Manakosten Eures nächsten Einsatzes von 'Blitzschlag', 'Kettenblitzschlag', 'Geringe Welle der Heilung' oder 'Lavaeruption' um 20% verringert werden. Diese Chance ist um 50% erhöht, während Eure Waffenhandwaffe mit 'Waffe des Windzorns' belegt ist, und um weitere 50% erhöht, wenn Ihr eine Zweihandwaffe führt. Bis zu 5-mal stapelbar. Hält 30 Sek. lang an." }
entries[410101] = { ["name"] = "Hosen prägen - Erdschild", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Erdschild':\n\nSchützt das Ziel mit einem Erdschild, der die Erhöhung der Zauberzeit oder Verringerung der Kanalisierungsdauer durch erlittenen Schaden um 30% verringert und Angriffe das geschützte Ziel um [Quellwert] Gesundheit heilen lässt. Dieser Effekt tritt nur einmal alle paar Sekunden auf. 9 Aufladungen. Hält 10 Min. lang an. Der Erdschild kann immer nur auf jeweils einem Ziel aktiv sein.", ["unresolvedValues"] = true }
entries[410103] = { ["name"] = "Stiefel prägen - Geist des Alphas", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel\nPrägt Eure Stiefel mit der Rune 'Geist des Alphas':\n\nErfüllt das Ziel mit dem Geist eines Alphawolfes, was die generierte Bedrohung des Ziels 30 Min. lang um 45% erhöht. Maximal 1 Ziel. Wenn der Schamane diesen Zauber nicht auf sich selbst wirkt, erhält er 'Treuer Beta', was 30 Min. lang seinen verursachten körperlichen Schaden um 5% erhöht und jegliche erzeugte Bedrohung um 30% verringert. Ein Ziel kann nicht gleichzeitig mit 'Geist des Alphas' und 'Treuer Beta' belegt sein." }
entries[410104] = { ["name"] = "Handschuhe prägen - Lavapeitsche", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Lavapeitsche':\n\nLädt Eure Schildhandwaffe mit Lava auf, verursacht sofort 100% Waffenschaden der Schildhandwaffe. Der Schaden ist um 150% erhöht, wenn Eure Schildhandwaffe mit 'Flammenzunge' verzaubert ist." }
entries[410105] = { ["name"] = "Armschienen prägen - Springflut", ["text"] = "Wirken in 3 sek.\nBenötigt Armschienen\nPrägt Eure Armschienen mit der Rune 'Springflut':\n\nHeilt ein verbündetes Ziel um [Quellwert] bis [Quellwert] Gesundheit und im Verlauf von 15 Sek. um weitere [Quellwert] Gesundheit. Wenn Ihr innerhalb von 15 Sek. 'Kettenheilung' auf dieses Hauptziel wirkt, wird die hervorgerufene Heilung um 25% erhöht. Dieser Zauber löst außerdem 'Erwachen der Ahnen' aus.", ["unresolvedValues"] = true }
entries[410107] = { ["name"] = "Hosen prägen - Weg der Erde", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Weg der Erde':\n\nWährend 'Waffe des Felsbeißers' auf Eurer Waffenhand aktiv ist und Ihr einen Schild ausgerüstet habt, erzeugt Ihr 65% mehr Bedrohung, erhaltet 25% mehr Gesundheit, erleidet 10% weniger Schaden. Eure Chance, von Nahkampfangriffen kritisch getroffen zu werden, ist um 6% verringert. Euer 'Erdschock' verspottet Ziele, damit sie Euch angreifen, und hat eine von anderen Schockzaubern getrennte Abklingzeit, aber seine Reichweite wird auf Nahkampfreichweite verringert. Die Reichweite Eurer Zauber 'Blitzschlag', 'Kettenblitzschlag', 'Kettenheilung', 'Welle der Heilung' und 'Lavaeruption' ist jedoch um 20 Meter verringert." }
entries[410109] = { ["name"] = "Gürtel prägen - Zuverlässiger Schuss", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Zuverlässiger Schuss':\n\nEin zuverlässiger Schuss, der 100% Schaden mit Distanzwaffen verursacht." }
entries[410110] = { ["name"] = "Brustteil prägen - Meister der Tiere", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Meister der Tiere':\n\nErhöht Schaden und Gesundheit Eures Tiers um 15% und seine Fokusregeneration um 50%. Außerdem verspottet das 'Knurren' Eures Tiers das Ziel 3 Sek. lang." }
entries[410111] = { ["name"] = "Hosen prägen - Tödlicher Schuss", ["text"] = "Wirken in 3 sek.\nBenötigt Hosen\nPrägt Eure Hosen mit der Rune 'Tödlicher Schuss':\n\nIhr versucht, ein verletztes Ziel mit einem Distanzangriff zu töten, der 100% Waffenschaden plus [Quellwert] verursacht. 'Tödlicher Schuss' hat keine Minimaldistanz, und seine Abklingzeit wird zurückgesetzt, wenn er gegen einen Gegner mit 20% oder weniger Gesundheit eingesetzt wird.", ["unresolvedValues"] = true }
entries[410113] = { ["name"] = "Brustteil prägen - Meister der Treffsicherheit", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Meister der Treffsicherheit':\n\nErhöht Eure kritische Trefferchance um 5% und verringert die Manakosten aller Eurer Schussfähigkeiten um 25%." }
entries[410114] = { ["name"] = "Gürtel prägen - Schwäche aufdecken", ["text"] = "Wirken in 3 sek.\nBenötigt Gürtel\nPrägt Euren Gürtel mit der Rune 'Schwäche aufdecken':\n\nEure kritischen Treffer mit Nahkampf- und Distanzangriffen erhöhen 7 Sek. lang Eure Angriffskraft um 40% Eurer aktuellen Beweglichkeit." }
entries[410115] = { ["name"] = "Kobraschlächter", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Kobraschlächter':\n\n'Mungobiss' hat bei jedem Eurer Nahkampfangriffe eine Chance von 10%, aktiviert zu werden, sowie eine Chance von 100%, wenn der Gegner ausweicht. Diese Chance sammelt sich an und steigt durch jeden Angriff in Folge, bei dem sie nicht zurückgesetzt wird, um 10%. 'Mungobiss' verursacht zusätzlichen Schaden in Höhe von 45% Eurer Angriffskraft." }
entries[410116] = { ["name"] = "Stiefel prägen - Beidhändigkeitsspezialisierung", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel\nPrägt Eure Stiefel mit der Rune 'Beidhändigkeitsspezialisierung':\n\nErhöht den von Eurer Schildhandwaffe verursachten Schaden um 60% und führt dazu, dass Euer 'Raptorstoß' mit beiden Waffen trifft, wenn Ihr beidhändig kämpft." }
entries[410118] = { ["name"] = "Stiefel prägen - Fallenschleuder", ["text"] = "Wirken in 3 sek.\nBenötigt Stiefel\nPrägt Eure Stiefel mit der Rune 'Fallenschleuder':\n\nEure Eiskältefallen, Feuerbrandfallen und Sprengfallen können jetzt an jedem Ort innerhalb von 35 Metern ausgelegt werden. Außerdem haben Eure feuer- und frostbasierten Fallen jetzt getrennte gemeinsame Abklingzeiten." }
entries[410121] = { ["name"] = "Handschuhe prägen - Schimärenschuss", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Schimärenschuss':\n\nVerursacht 135% Waffenschaden, erneuert die Dauer des auf das Ziel wirkenden Stiches oder Bisses und löst einen Effekt aus:\n\nSchlangenbiss - Verursacht sofort 48% des von Eurem Schlangenbiss verursachten Schadens.\n\nVipernbiss - Stellt sofort 60% des von Eurem Vipernbiss abgezogenen Manas bei Euch wieder her.\n\nSkorpidstich - Versucht, das Ziel 10 Sek. lang zu entwaffnen. Dieser Effekt kann nur einmal pro Minute auftreten." }
entries[410122] = { ["name"] = "Brustteil prägen - Einsamer Wolf", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust\nPrägt Euer Brustteil oder Eure Robe mit der Rune 'Einsamer Wolf':\n\nIhr verursacht mit allen Angriffen 25% mehr Schaden, während Ihr kein Tier aktiviert habt." }
entries[410123] = { ["name"] = "Handschuhe prägen - Explosivschuss", ["text"] = "Wirken in 3 sek.\nBenötigt Handschuhe\nPrägt Eure Handschuhe mit der Rune 'Explosivschuss':\n\nFeuert ein Explosivgeschoss in das gegnerische Ziel, das allen Gegnern innerhalb von 8 Metern [Fernkampfangriffskraft * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] bis [Fernkampfangriffskraft * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] Feuerschaden zufügt. Die Sprengladung verursacht 2 Sek. lang pro Sekunde weiteren Schaden." }
entries[410140] = { ["name"] = "Spinnengift" }
entries[410144] = { ["name"] = "Wilde Verteidigung", ["text"] = "Sofort\nBenötigt Bärengestalt, Terrorbärengestalt" }
entries[410156] = { ["name"] = "Sturmschlag", ["text"] = "Unbegrenzte Reichweite\nSofort\nGewährt Euch einen zusätzlichen Angriff. Zusätzlich werden die nächsten 2 Quellen des Naturschadens, der dem Ziel zugefügt wird, um 20% erhöht. Hält 12 Sek. lang an." }
entries[410163] = { ["name"] = "Nekrotische Infektion" }
