entries[412115] = { ["name"] = "Fortgeschrittener Schutzzauber", ["text"] = "Eure Zauber 'Manaschild', 'Frostzauberschutz' und 'Feuerzauberschutz' können jetzt auf verbündete Ziele gewirkt werden und absorbieren 100% mehr Schaden. 'Manaschild' verbraucht 50% weniger Mana pro absorbiertem Schaden. Außerdem wird 'Geringen Fluch aufheben' durch 'Großen Fluch aufheben' ersetzt.\n\nEntfernt 1 Fluch und 1 schädlichen Magieeffekt von einem verbündeten Ziel." }
