entries[412532] = { ["name"] = "Zauberfrostblitz", ["text"] = "12% von Grundmana 30 Meter Reichweite\nWirken in 2.5 sek.\nSchleudert einen Zauberfrostblitz auf den Gegner, der [Quellwert] bis [Quellwert] Zauberfrostschaden verursacht und seine Bewegungsgeschwindigkeit 9 Sek. lang um 40% verringert. Der Schaden dieses Zaubers wird gegen den jeweils geringeren Frost- oder Arkanwiderstandswert des Ziels gerechnet und zählt sowohl als Frost- als auch als Arkanschaden.", ["unresolvedValues"] = true }
