entries[412758] = { ["name"] = "Verbrennen", ["text"] = "14% von Grundmana 30 Meter Reichweite\nWirken in 2.25 sek.\nVerbrennt Euren Gegner, fügt ihm [Quellwert] bis [Quellwert] Schaden zu und erhöht jeglichen von Euch verursachten Feuerschaden 15 Sek. lang um 40%.", ["unresolvedValues"] = true }
