entries[412787] = { ["name"] = "Unterbrechen", ["text"] = "5% von Grundmana Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nErstickt Euren Gegner mit einer Welle schattenhafter Energie, die 10 Schaden verursacht, das Wirken von Zaubern unterbricht und 5 Sek. lang verhindert, dass Zauber dieser Art gewirkt werden können." }
entries[412788] = { ["name"] = "Dämonischer Ansturm", ["text"] = "5% von Grundmana 8 - 25 Meter Reichweite\nSofort 15 sek. Abklingzeit\nStürmt auf einen Gegner zu und betäubt ihn für 1 Sek. Kann nicht im Kampf verwendet werden." }
