entries[412790] = { ["name"] = "Infernalischer Schlag", ["text"] = "8 - 25 Meter Reichweite\nSofort 45 sek. Abklingzeit\nSpringt durch die Luft und schmettert auf alle Gegner im Umkreis von 8 Metern um das Zielgebiet hinab, verursacht 100 Schattenschaden und betäubt sie für 2 Sek." }
entries[412798] = { ["name"] = "Tanz des Tückischen", ["text"] = "Ihr und Euer Dämon erhaltet jedes Mal, wenn Ihr einem Gegner einen kritischen Treffer zufügt, eine Ausweichchance in Höhe von 70% Eurer kritischen Zaubertrefferchance. Ihr beide gewinnt außerdem 2% Eures maximalen Manas zurück." }
